import {ProtocolProvider} from "@/r2modmanPlus/src/providers/generic/protocol/ProtocolProvider";

export const OverwolfProtocolProvider: ProtocolProvider = {
    getPublicAssetUrl: url => {
        // If on a served environment, use public URL
        if (window.location.origin.startsWith("http")) {
            return `${window.location.origin}${url}`
        }
        // If not served via HTTP, assume overwolf-extension packaging
        return `${window.location.origin}/dist${url}`
    }
}