import {RouteConfig} from "vue-router";
import ManagerInformation from "@/r2modmanPlus/src/_managerinf/ManagerInformation";
import Profile from "@/r2modmanPlus/src/model/Profile";
import { isDevMode } from "../utils/global";

export const appTitle = () => `${ManagerInformation.APP_NAME} (${ManagerInformation.VERSION.toString()})`;
const profileTitle = () => `${appTitle()} - ${Profile.getActiveProfile().getProfileName()}`;

const routes: RouteConfig[] = [
    {
        name: "index",
        path: "/",
        component: () => import("@/r2modmanPlus/src/pages/GameSelectionScreen.vue"),
        meta: {title: appTitle}
    },
    {
        name: "splash",
        path: "/splash/",
        component: () => import("@/overwolf/views/Splash.vue"),
        meta: {title: appTitle}
    },
    {
        name: "profiles",
        path: "/profiles/",
        component: () => import("@/r2modmanPlus/src/pages/Profiles.vue"),
        meta: {title: appTitle}
    },
    {
        path: "/",
        component: () => import("@/overwolf/components/manager/ManagerLayout.vue"),
        meta: {title: appTitle},
        children: [
            {
                name: "manager",
                path: "manager/",
                component: () => import("@/r2modmanPlus/src/pages/Manager.vue"),
                meta: {title: profileTitle},
                children: [
                    {
                        name: "manager.installed",
                        path: "installed/",
                        alias: "",
                        components: {
                            subview: () => import("@/r2modmanPlus/src/components/views/InstalledModView.vue")
                        },
                        meta: {title: profileTitle},
                    },
                    {
                        name: "manager.online",
                        path: "online/",
                        components: {
                            subview: () => import("@/r2modmanPlus/src/components/views/OnlineModView.vue")
                        },
                        meta: {title: profileTitle},
                    },
                    {
                        name: "manager.settings",
                        path: "settings/",
                        components: {
                            subview: () => import("@/overwolf/components/overrides/OverwolfSettingsView.vue")
                        },
                        meta: {title: profileTitle}
                    }
                ]
            },
            {
                name: "config-editor",
                path: "/config-editor",
                component: () => import("@/r2modmanPlus/src/pages/ConfigEditor.vue"),
                meta: {title: profileTitle}
            },
            {
                name: "help",
                path: "help/",
                component: () => import("@/overwolf/views/Help.vue"),
                meta: {title: profileTitle}
            },
            {
                name: "downloads",
                path: "downloads/",
                component: () => import("@/r2modmanPlus/src/pages/DownloadMonitor.vue"),
                meta: {title: profileTitle}
            }
        ]
    },
    {
        name: "user",
        path: "/user/",
        component: () => import("@/overwolf/views/UserAccount.vue"),
        meta: {title: appTitle}
    }
];

if (isDevMode) {
    routes.push({
        name: "dev-tools",
        path: "/dev/",
        component: () => import("@/overwolf/views/DevTools.vue"),
        meta: {title: () => `${appTitle()} - Dev tools`}
    })
}

export default routes;
