import { isDateString } from '@/overwolf/utils/global';

type JsonObject = Partial<{ [key: string]: Json }>;
export type Json = boolean | number | string | null | JsonObject | Array<Json>;

// User profile from Overwolf API
export type OwProfile = overwolf.profile.UserProfile & JsonObject;

export const isOwProfile = (profile: any): profile is OwProfile =>
    typeof profile.avatar === "string" &&
    typeof profile.nickname === "string" &&
    typeof profile.username === "string";

// User Profile from Thunderstore API
export interface TsProfile extends JsonObject {
    username: string|null;
    capabilities: string[];
    subscription: {
        expires: string|null;  // ISO 8601 date string
    };
    rated_packages: string[];
    teams: string[];
}

export const isTsProfile = (profile: any): profile is TsProfile => {
    const expires = profile?.subscription?.expires;
    const isValidExpiry = expires === null || isDateString(expires);
    return typeof profile.username === "string" && isValidExpiry;
}

// Data returned by Thunderstore API when logging in via mod manager.
export interface TsSession {
    session_id: string;
    profile: TsProfile;
}

export const isTsSession = (session: any): session is TsSession =>
    typeof session.session_id === "string" && isTsProfile(session.profile);
