<template>
    <div id="app">
        <SettingsLoader :logError="logError" :openLink="openLink">
            <App />
        </SettingsLoader>
    </div>
</template>

<script lang="ts" setup>
import * as Sentry from "@sentry/vue";

import App from "@/overwolf/App.vue";
import {openLink} from "@/overwolf/utils/global";
import SettingsLoader from "@/r2modmanPlus/src/components/SettingsLoader.vue";
import R2Error from "@/r2modmanPlus/src/model/errors/R2Error";
import {provideStoreImplementation} from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import Store from "@/overwolf/store";
import {providePathImplementation} from "@/r2modmanPlus/src/providers/node/path/path";
import {OverwolfPathImplementation} from "@/overwolf/provider_overrides/node/path/OverwolfPath";
import {provideBufferImplementation} from "@/r2modmanPlus/src/providers/node/buffer/buffer";
import {OverwolfBuffer} from "@/overwolf/provider_overrides/node/buffer/OverwolfBuffer";
import {provideChildProcessImplementation} from "@/r2modmanPlus/src/providers/node/child_process/child_process";
import {OverwolfChildProcess} from "@/overwolf/provider_overrides/node/child_process/OverwolfChildProcess";

provideStoreImplementation(() => Store);
providePathImplementation(() => OverwolfPathImplementation);
provideBufferImplementation(() => OverwolfBuffer);
provideChildProcessImplementation(() => OverwolfChildProcess);

function logError(error: R2Error) {
    if (import.meta.env.MODE === 'development') {
      console.error("TSMM_DEV_MODE:", error);
    }
    Sentry.captureException(error);
}
</script>
