import Vuex, { ActionContext, GetterTree, MutationTree } from 'vuex'

import { State as R2State, store as R2Store } from '@/r2modmanPlus/src/store/index';
import { AuthModule } from '@/overwolf/store/AuthModule';
import { TsModalsModule } from '@/overwolf/store/ModalsModule';
import { TsProfileExportModule } from '@/overwolf/store/ProfileExportModule';
import { TsProfileModule } from '@/overwolf/store/ProfileModule';
import SubscriptionModule from '@/overwolf/store/SubscriptionModule';
import { TsModsModule } from '@/overwolf/store/TsModsModule';
import { UserSettingsModule } from '@/overwolf/store/UserSettingsModule';
import { isDevMode } from '@/overwolf/utils/global';
import ManagerSettings from '@/r2modmanPlus/src/r2mm/manager/ManagerSettings';

export interface State extends R2State {
    isDarkTheme: boolean;
};

type Context = ActionContext<State, State>;

const publicModules = {
    ...R2Store.modules,
    auth: AuthModule,
    modals: TsModalsModule,  // Overwrites R2Store.modules.modals
    profileExport: TsProfileExportModule,  // Overwrites R2Store.modules.profileExport
    profile: TsProfileModule,  // Overwrites R2Store.modules.profile
    subscription: SubscriptionModule,
    tsMods: TsModsModule,  // Overwrites R2Store.modules.tsMods
}

const modules = isDevMode
    ? {
        ...publicModules,
        userSettings: UserSettingsModule
    }
    : publicModules;

const store = {
    state: {
        ...R2Store.state,
        isDarkTheme: false,
    },

    actions: {
        ...R2Store.actions,

        async toggleTheme({ commit, state }: Context) {
            commit("setIsDarkTheme", !state.isDarkTheme);

            // Save updated value to Dexie store, where it's loaded the
            // next time the app is started.
            const settings = await ManagerSettings.getSingleton(state.activeGame);
            await settings.toggleDarkTheme();

            // This would apparently toggle Quasar's dark mode. It's not
            // required in TSMM, but I leave it here so it's not
            // forgotten if these changes get ported to R2MM.
            // await ThemeManager.apply();
        },
    },

    getters: <GetterTree<State, State>>{
        ...R2Store.getters,

        // Vue computed values don't seem to recalculate on changes when
        // pointed directly to state, but do if pointed to a getter.
        isDarkTheme: (state) => state.isDarkTheme,

        shownUsername: (state): string | undefined => {
            if (!isDevMode) {
                return undefined;
            }

            // Due to poor TS support in VueX v3 the main store doesn't
            // know about submodule stores.
            // @ts-ignore
            const username = state.auth.user.thunderstore?.username;

            // @ts-ignore
            return state.userSettings.isStreamerMode && username ? "********" : username;
        }
    },

    mutations: <MutationTree<State>>{
        ...R2Store.mutations,

        setIsDarkTheme: (state, value: boolean) => {
            state.isDarkTheme = value;
            document.documentElement.classList.toggle("html--dark", value);
        },
    },

    modules
};

export default new Vuex.Store<State>(store)
