import opentelemetry, { Span, SpanStatusCode, Tracer } from "@opentelemetry/api";
import { SemanticAttributes } from "@opentelemetry/semantic-conventions";

import ManagerInformation from "@/r2modmanPlus/src/_managerinf/ManagerInformation";
import CdnProvider from "@/r2modmanPlus/src/providers/generic/connection/CdnProvider";

export function getPackageListUpdateTracer(): Tracer {
    return opentelemetry.trace.getTracer(
        'thunderstore.mod-manager.package-list-update',
        `semver:${ManagerInformation.VERSION}`
    );
}

export function recordError(span: Span, err: unknown) {
    const error = err instanceof Error ? err : new Error(`${err}`);
    span.recordException(error);
    span.setStatus({
        code: SpanStatusCode.ERROR,
        message: error.message,
    });
}

export function recordSuccess(span: Span) {
    span.setStatus({code: SpanStatusCode.OK});
}

export function setPackageListUpdateSpanAttributes(
    span: Span,
    fileName: string,
    functionName: string,
    community: string
): void {
    span.setAttribute(SemanticAttributes.CODE_FILEPATH, fileName);
    span.setAttribute(SemanticAttributes.CODE_FUNCTION, functionName);
    span.setAttribute(SemanticAttributes.HTTP_METHOD, 'GET');
    span.setAttribute('thunderstore.community', community);
    span.setAttribute('thunderstore.cdn', CdnProvider.current.url);
}
