import GameManager from "@/r2modmanPlus/src/model/game/GameManager";

export default class PluginGlobals {

    private static _APP_NAME: string = "Thunderstore Mod Manager";

    static get APP_NAME(): string {
        return this._APP_NAME;
    }

    static set APP_NAME(value: string) {
        this._APP_NAME = value;
    }

    static get APP_ID(): string {
        return GameManager.activeGame.activePlatform.storeIdentifier || "";
    }
}