import GameRunnerProvider from "@/r2modmanPlus/src/providers/generic/game/GameRunnerProvider";
import R2Error from "@/r2modmanPlus/src/model/errors/R2Error";
import GameInstructions from "@/r2modmanPlus/src/r2mm/launching/instructions/GameInstructions";
import Profile from "@/r2modmanPlus/src/model/Profile";
import Game from "@/r2modmanPlus/src/model/game/Game";
import GameInstructionParser from "@/r2modmanPlus/src/r2mm/launching/instructions/GameInstructionParser";
import ManagerSettings from "@/r2modmanPlus/src/r2mm/manager/ManagerSettings";
import GameDirectoryResolverProvider from "@/r2modmanPlus/src/providers/ror2/game/GameDirectoryResolverProvider";
import LoggerProvider, {LogSeverity} from "@/r2modmanPlus/src/providers/ror2/logging/LoggerProvider";
import {Platform} from "@/r2modmanPlus/src/model/schema/ThunderstoreSchema";
import path from "path";
import FsProvider from "@/r2modmanPlus/src/providers/generic/file/FsProvider";
import PluginGlobals from "@/overwolf/PluginGlobals";
import OverwolfResult from "@/overwolf/provider_overrides/OverwolfResult";
import ChildProcess from "@/r2modmanPlus/src/providers/node/child_process/child_process";

export default class OverwolfGameRunner extends GameRunnerProvider {

    public async getGameArguments(game: Game, profile: Profile): Promise<string[] | R2Error> {
        const instructions = await GameInstructions.getInstructionsForGame(game, profile);
        return await GameInstructionParser.parseList(instructions.moddedParameterList, game, profile);
    }

    public async startModded(game: Game, profile: Profile): Promise<void | R2Error> {
        const args = await this.getGameArguments(game, profile);
        if (args instanceof R2Error) {
            return args
        }
        return this.start(game, args);
    }

    public async startVanilla(game: Game, profile: Profile): Promise<void | R2Error> {
        const instructions = await GameInstructions.getInstructionsForGame(game, profile);
        return this.start(game, instructions.vanillaParameterList);
    }

    async start(game: Game, args: string[]): Promise<void | R2Error> {
        return new Promise(async (resolve, reject) => {
            const settings = await ManagerSettings.getSingleton(game);
            let execString = "";
            let argString = "";
            const mappedArgs = args.map(value => `"${value}"`).join(' ');
            if (game.activePlatform.storePlatform === Platform.STEAM) {
                const steamDir = await GameDirectoryResolverProvider.instance.getSteamDirectory();
                if (steamDir instanceof R2Error) {
                    return resolve(steamDir);
                }
                execString = `${path.join(steamDir, "steam.exe")}`;
                argString = `-applaunch ${game.activePlatform.storeIdentifier} ${mappedArgs}`;
            } else {
                const gameDir = await GameDirectoryResolverProvider.instance.getDirectory(game);
                if (gameDir instanceof R2Error) {
                    return gameDir;
                }
                const foundExe = (await FsProvider.instance.readdir(gameDir))
                    .find(file => game.exeName.indexOf(file) >= 0);
                if (foundExe === undefined) {
                    return resolve(new R2Error("No executable found in the game folder", `The game folder did not contain one of the following executables:\n${game.exeName.join(", ")}`, "Set the correct game folder in the Settings screen"));
                }
                execString = path.join(gameDir, foundExe);
                argString = mappedArgs;
            }
            execString = execString.replace("/", "\\");

            LoggerProvider.instance.Log(LogSeverity.INFO, `Running command: ${execString} ${argString} ${settings.getContext().gameSpecific.launchParameters}`);

            ChildProcess.exec(execString, `${argString} ${settings.getContext().gameSpecific.launchParameters}`, (error: Error) => {
                // "error" is actually a string when passed via Plugin.
                // This type information is incompatible with the provider.
                const r = error as unknown as string;

                const result = JSON.parse(r) as OverwolfResult;
                if (result.TypeString === "ERROR") {
                    return reject(new R2Error("Failed to start modded", result.Value, null));
                }
                return resolve();
            });
        });
    }
}
