import type { ActionTree, GetterTree, MutationTree } from 'vuex';

import { State as RootState } from '@/overwolf/store/index';
import { isOwProfile, OwProfile, TsProfile } from "@/overwolf/types";
import {
    getThunderstoreProfile,
    terminateThunderstoreSession,
    tryGetUserProfile,
} from '@/overwolf/utils/auth';
import { isDateString } from '@/overwolf/utils/global';
import { StorageManager } from '@/overwolf/utils/storage';

type State = {
    sessionId?: string;  // Thunderstore session id
    user: {
        overwolf?: OwProfile;
        thunderstore?: TsProfile;
    };
}

type LoginParams = {
    owToken: string;
    tsSessionId: string;
    tsProfile: TsProfile;
}

const persistentStorage = new StorageManager("auth");
const STORAGE_KEY = "state";

const loadFromStorage = () => persistentStorage.getJSON<State>(STORAGE_KEY) ?? {
    sessionId: undefined,
    user: {}
};

const saveToStorage = (state: State) => persistentStorage.setJSON(STORAGE_KEY, state);

const clearStorage = () => persistentStorage.removeValue(STORAGE_KEY);


export const AuthModule = {
    namespaced: true,
    state: loadFromStorage,

    getters: <GetterTree<State, RootState>>{
        isAuthenticated: (state) => state.user.thunderstore?.username !== undefined,

        subscriptionExpires: (state): Date|null => {
            const expiry = state.user.thunderstore?.subscription?.expires;

            if (expiry === undefined || expiry === null) {
                return null;
            }

            if (isDateString(expiry)) {
                return new Date(expiry);
            }

            throw new Error(`Invalid subscription expiration "${expiry}" in storage`);
        }
    },

    mutations: <MutationTree<State>>{
        clearStore: (state) => {
            state.sessionId = undefined;
            state.user = {};
        },
        setState: (state, newState: State) => {
            state.sessionId = newState.sessionId;
            state.user = newState.user;
        },
    },

    actions: <ActionTree<State, RootState>>{
        async login({ commit, state }, params: LoginParams) {
            const { owToken, tsSessionId, tsProfile } = params;

            // Profile fetching might fail silently, but it's okay since
            // the information is used only for eye candy currently.
            const profile = await tryGetUserProfile(owToken);

            const newState = {
                sessionId: tsSessionId,
                user: {
                    overwolf: isOwProfile(profile) ? profile : undefined,
                    thunderstore: tsProfile
                }
            };

            commit("setState", newState);
            saveToStorage(state);
        },

        async logout({ commit, state }) {
            if (state.sessionId) {
                // Intentionally skip awaiting since we're not
                // interested in the result.
                terminateThunderstoreSession(state.sessionId);
            }

            commit("clearStore");
            clearStorage();
        },

        // Check if the stored Thunderstore session is still valid by
        // attempting to refresh user's Thunderstore profile.
        async verifySession({ commit, state }) {
            if (!state.sessionId) {
                return;
            }

            const profile = await getThunderstoreProfile(state.sessionId);

            // Update stored profile if session is still valid. Clear
            // storage if session has expired. If server can't be
            // reached or the response had malformed payload, keep using
            // the stored values as a cache.
            if (profile.status === "refreshed") {
                const newState = {...state};
                newState.user.thunderstore = profile.profile;
                commit("setState", newState);
            } else if (profile.status === "expired") {
                commit("clearStore");
                clearStorage();
            }
        }
    },
}
