import ZipProvider from "@/r2modmanPlus/src/providers/generic/zip/ZipProvider";
import ZipEntryInterface from "@/r2modmanPlus/src/providers/generic/zip/ZipEntryInterface";
import ZipBuilder from "@/r2modmanPlus/src/providers/generic/zip/ZipBuilder";
import ZipCreatorInterface from "@/overwolf/provider_overrides/ZipProvider/ZipCreatorInterface";
import R2Error from "@/r2modmanPlus/src/model/errors/R2Error";
import PluginGlobals from "@/overwolf/PluginGlobals";
import ZipperInterface from "@/overwolf/provider_overrides/ZipProvider/ZipperInterface";
import OverwolfResult from "@/overwolf/provider_overrides/OverwolfResult";

export default class OverwolfZipProvider extends ZipProvider {

    private zipperPlugin!: ZipperInterface;
    private zipCreatorPlugin!: ZipCreatorInterface;
    private loaded: boolean = false;

    constructor() {
        super();
        // @ts-ignore-line
        const ow = overwolf;
        ow.extensions.current.getExtraObject("zipper", (result: any) => {
            if (result.status === "success") {
                this.zipperPlugin = result.object;
            }
            ow.extensions.current.getExtraObject("zip-creator", (result: any) => {
                if (result.status === "success") {
                    this.zipCreatorPlugin = result.object;
                    this.loaded = true;
                }
            });
        });
    }

    public async waitForPlugin(): Promise<void> {
        return new Promise(resolve => {
            if (this.loaded) {
                resolve();
            } else {
                const interval = setInterval(() => {
                    if (this.loaded) {
                        resolve();
                        clearInterval(interval);
                    }
                }, 10);
            }
        })
    }

    async extractAllTo(zip: string | Buffer, outputFolder: string): Promise<void> {
        return new Promise((resolve, reject) => {
            this.zipperPlugin.ExtractAllTo(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, zip, outputFolder, r => {
                const result = JSON.parse(r);
                if (result.TypeString === "ERROR") {
                    return reject(new R2Error("Error extracting all files from zip", result.Value, null));
                } else if (result.TypeString === "ERROR_DISK_SPACE") {
                    const err = new R2Error("Not enough space remaining on disk", result.Value, "Clean the mod cache via Settings or change the drive the data folder is located on.");
                    err.errorReferenceString = result.TypeString;
                    return reject(err);
                }
                resolve();
            });
        });
    }

    async extractEntryTo(zip: string | Buffer, target: string, outputPath: string): Promise<void> {
        return new Promise((resolve, reject) => {
            this.zipperPlugin.ExtractEntryTo(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, zip, target, outputPath, r => {
                const result = JSON.parse(r);
                if (result.TypeString === "ERROR") {
                    return reject(new R2Error(`Error extracting file from zip: ${target}`, result.Value, null));
                } else if (result.TypeString === "ERROR_DISK_SPACE") {
                    const err = new R2Error("Not enough space remaining on disk", result.Value, "Clean the mod cache via Settings or change the drive the data folder is located on.");
                    err.errorReferenceString = result.TypeString;
                    return reject(err);
                }
                resolve();
            });
        });
    }

    async getEntries(zip: string | Buffer): Promise<ZipEntryInterface[]> {
        return new Promise((resolve, reject) => {
            this.zipperPlugin.GetEntries(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, zip, r => {
                const result = JSON.parse(r) as OverwolfResult;
                if (result.TypeString === "ERROR") {
                    return reject(new R2Error(`Error getting entries of zip`, result.Value, null));
                }
                const resultValue = result.Value as string[];
                const mappedResults = resultValue.map(value => {
                    return {
                        entryName: value
                    } as ZipEntryInterface;
                });
                return resolve(mappedResults);
            });
        });
    }

    async readFile(zip: string | Buffer, file: string): Promise<Buffer | null> {
        return new Promise(resolve => {
            this.zipperPlugin.ReadFile(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, zip, file, r => {
                const result = JSON.parse(r);
                if (result.TypeString === "ERROR") {
                    resolve(null);
                }
                resolve(result.Value);
            });
        });
    }

    zipBuilder(): ZipBuilder {
        return new OverwolfZipBuilder(this.zipCreatorPlugin);
    }

}

export class OverwolfZipBuilder extends ZipBuilder {

    private zipCreatorPlugin: ZipCreatorInterface;
    private zipKey: string | undefined;

    constructor(creatorPlugin: any) {
        super();
        this.zipCreatorPlugin = creatorPlugin;
        this.zipCreatorPlugin.RequestKey(r => {
            const result = JSON.parse(r);
            if (result.TypeString === "STRING") {
                this.zipKey = result.Value;
            } else {
                throw new R2Error("Error requesting zip key", result.Value, null);
            }
        })
    }

    private async awaitZipKey(): Promise<string> {
        return new Promise(resolve => {
            if (this.zipKey !== undefined) {
                resolve(this.zipKey);
            }
            const interval = setInterval(() => {
                if (this.zipKey !== undefined) {
                    clearInterval(interval);
                    resolve(this.zipKey);
                }
            }, 10);
        })
    }

    async addBuffer(fileName: string, contents: Buffer): Promise<void> {
        return this.awaitZipKey().then(key => {
            return new Promise(resolve => {
                this.zipCreatorPlugin.AddBuffer(key, fileName, [...contents], r => {
                    const result = JSON.parse(r);
                    if (result.TypeString === "ERROR") {
                        throw new R2Error("Error adding buffer", result.Value, null);
                    }
                    resolve();
                });
            });
        });
    }

    async addFolder(zippedFolderName: string, folderName: string): Promise<void> {
        return this.awaitZipKey().then(key => {
            return new Promise(resolve => {
                console.log("FolderName:", folderName);
                console.log("ZippedFolderName:", zippedFolderName);
                this.zipCreatorPlugin.AddFolder(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, key, folderName, zippedFolderName, r => {
                    const result = JSON.parse(r);
                    if (result.TypeString === "ERROR") {
                        throw new R2Error("Error adding folder", result.Value, null);
                    }
                    resolve();
                });
            });
        });
    }

    async createZip(outputPath: string): Promise<void> {
        return this.awaitZipKey().then(key => {
            return new Promise((resolve, reject) => {
                this.zipCreatorPlugin.Create(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, key, outputPath, r => {
                    const result = JSON.parse(r);
                    if (result.TypeString === "ERROR") {
                        reject(new R2Error("Error creating zip", result.Value));
                    }
                    resolve();
                });
            });
        });
    }
}
