import LinkProvider from '@/r2modmanPlus/src/providers/components/LinkProvider';

export default class OverwolfLinkImpl extends LinkProvider {

    private plugin: any;
    private loaded: boolean = false;

    constructor() {
        super();
        // @ts-ignore-line
        overwolf.extensions.current.getExtraObject("explorer-operations", (result) => {
            if (result.status === "success") {
                this.plugin = result.object;
                this.loaded = true;
            }
        });
    }

    public async waitForPlugin(): Promise<void> {
        return new Promise(resolve => {
            if (this.loaded) {
                resolve();
            } else {
                const interval = setInterval(() => {
                    if (this.loaded) {
                        resolve();
                        clearInterval(interval);
                    }
                }, 10);
            }
        });
    }
    
    public openLink(url: string): void {
        this.plugin.OpenLink(url, () => {});
    }

    public selectFile(url: string): void {
        this.plugin.SelectFile(url, () => {});
    }

}