<template>
    <div id="titlebar" class="z-max non-selectable" @dblclick.self="toggleMaximiseAndRestore">
        <TsLogo width="108px" height="16px" />
        <span class="version">{{ appVer }}</span>

        <div class="actions">
            <!-- <FaButton icon="fa-bell" :onClick="() => null" /> -->
            <FaButton
                v-if="isDevMode"
                icon="fa-cog"
                :onClick="() => router.push({name: 'dev-tools'})"
            />
            <FaButton
                :icon="`${isDarkTheme ? 'fa-sun-bright' : 'fa-moon'}`"
                :iconStyle="`${isDarkTheme ? 'fa-regular' : 'fa-solid'}`"
                :onClick="() => store.dispatch('toggleTheme')"
            />
            <LoginButton v-if="isDevMode" />
        </div>

        <div class="window-actions">
            <FaButton icon="fa-dash" :onClick="minimise" />
            <FaButton
                :icon="`${windowMaximised ? 'fa-window-restore' : 'fa-window-maximize'}`"
                :onClick="toggleMaximiseAndRestore"
            />
            <FaButton icon="fa-xmark-large" :onClick="close" class="danger" />
        </div>
    </div>
</template>

<script lang="ts" setup>
import FaButton from "@/overwolf/components/FaButton.vue";
import LoginButton from "@/overwolf/components/LoginButton.vue";
import TsLogo from "@/overwolf/components/TsLogo.vue";
import {OverwolfWindow} from "@/overwolf/overwolf_specific/OverwolfWindow";
import ManagerInformation from "@/r2modmanPlus/src/_managerinf/ManagerInformation";
import {isDevMode} from "../utils/global";
import {computed, onMounted, onUnmounted, ref} from "vue";
import {getStore} from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import {State} from "@/overwolf/store";
import {useRouter} from "vue-router";

const store = getStore<State>();
const router = useRouter();

const appVer = ref(ManagerInformation.VERSION);
const window = ref(new OverwolfWindow());
const windowMaximised = ref(false);

const isDarkTheme = computed(() => store.getters["isDarkTheme"]);

onMounted(async () => {
    const windowState = await window.value.getWindowState();
    windowMaximised.value = windowState.window_state === "maximized";
    window.value.dragMove(document.getElementById("titlebar")!);

    overwolf.windows.onStateChanged.addListener(onWindowChange);

    appVer.value = ManagerInformation.VERSION;
});

onUnmounted(() => {
    overwolf.windows.onStateChanged.removeListener(onWindowChange);
});

function onWindowChange(state: any) {
    windowMaximised.value = state.window_state === "maximized";
}

function close() {
    window.value.close();
}

function minimise() {
    window.value.minimize();
}

function toggleMaximiseAndRestore() {
    windowMaximised.value ? window.value.restore() : window.value.maximize();
}
</script>

<style lang="scss" scoped>
#titlebar {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    padding: 4px 0 4px 16px;
    border-bottom: 3px solid var(--TSDC-layout-border);
    background-color: var(--TSDC-bg-dark);
    color: var(--TSSC-LM-text-ternary);
}

.ts-logo {
    color: #222;
}

.version {
    margin-right: auto;
    font-size: 11px;
    font-weight: 600;
}

.actions {
    display: flex;
    gap: 8px;
}

.window-actions {
    display: flex;
    margin: -4px 0 -4px 20px; // Offset #titlebar padding for hover effects

    button::v-deep {
        width: 40px;
        height: 40px;
        border-radius: 0;

        &:hover {
            background: rgba(0, 0, 0, 0.05);
        }

        svg {
            width: 12px;
            height: 12px;
        }
    }
}

button.danger:hover {
    color: #fff;
    background-color: var(--TSSC-accent-red);
}

.html--dark {
    .ts-logo {
        color: #fff;
    }

    .window-actions button::v-deep:hover {
        color: var(--TSSC-text-link-hover);
        background-color: var(--TSSC-background-layer-2);

        &.danger {
            background-color: var(--TSSC-accent-red);
        }
    }
}
</style>
