import ModalsModule from "@/r2modmanPlus/src/store/modules/ModalsModule";

interface State extends ReturnType<typeof ModalsModule.state> {
    isOverwolfLoginModalOpen: boolean;
}

// Augment r2mm's ModalsModule with modals only available in tsmm.
export const TsModalsModule = {
    state: (): State => ({
        ...ModalsModule.state(),
        isOverwolfLoginModalOpen: false,
    }),

    mutations: {
        ...ModalsModule.mutations,

        closeOverwolfLoginModal: function(state: State): void {
            state.isOverwolfLoginModalOpen = false;
        },

        openOverwolfLoginModal: function(state: State): void {
            state.isOverwolfLoginModalOpen = true;
        },
    }
};
