import * as path from "path";
import {OverwolfPathProvider} from "@/overwolf/provider_overrides/node/path/OverwolfPathProvider";

export const OverwolfPathImplementation: OverwolfPathProvider = {
    basename: (...args) => path.basename(...args),
    dirname: (...args) => path.dirname(...args),
    extname: (...args) => path.extname(...args),
    join: (...args) => path.join(...args),
    relative: (...args) => path.relative(...args),
    resolve: (...args) => path.resolve(...args),
    normalize: (...args) => path.normalize(...args),
    get sep() {
        return path.sep;
    },
};