import * as Sentry from "@sentry/vue";

export class OverwolfAdManager {
    private static AD_CLASS: any;

    public static async waitForLoad(): Promise<void> {
        while (!this.AD_CLASS) {
            // @ts-ignore
            if (typeof OwAd !== "undefined" && typeof OwAd !== null) {
                // @ts-ignore
                this.AD_CLASS = OwAd;
            } else {
                await new Promise(resolve => setTimeout(resolve, 100));
            }
        }
    }

    public static async createAd(element: HTMLElement, width: number, height: number): Promise<any> {
        await OverwolfAdManager.waitForLoad();
        return new OverwolfAdManager.AD_CLASS(element, {size: {width: width, height: height}});
    }
}

export default class OverwolfAdInstance {
    private ad: any | null = null;
    private lastVisibility: boolean = false;
    private shouldBeVisibleInWindowState: boolean = true;
    private isAdLoading: boolean = false;
    private readonly element: HTMLElement;
    private readonly windowListener: any = undefined;
    private readonly width: number;
    private readonly height: number;

    constructor(element: HTMLElement, width: number, height: number) {
        this.element = element;
        this.width = width;
        this.height = height;
        this.windowListener = this.onWindowStateChanged.bind(this);
        overwolf.windows.onStateChanged.addListener(this.windowListener);
        this.refreshAd();
    }

    public deconstruct() {
        overwolf.windows.onStateChanged.removeListener(this.windowListener);
        this.removeAd();
    }

    private async refreshAd() {
        if (!this.ad && !this.isAdLoading) {
            this.isAdLoading = true;
            try {
                this.ad = await OverwolfAdManager.createAd(this.element, this.width, this.height);
            } catch (e) {
                Sentry.captureException(e);
            } finally {
                this.isAdLoading = false;
            }
        }
        else if (this.ad) {
            await this.ad.refreshAd();
        }
    }

    private async removeAd() {
        if (this.ad) {
            await this.ad.removeAd();
        }
    }

    private async recheckVisibility() {
        const shouldBeVisible = this.shouldBeVisibleInWindowState;
        if (shouldBeVisible && !this.lastVisibility) {
            try {
                await this.refreshAd();
            }
            catch { }
        } else if (!shouldBeVisible && this.lastVisibility) {
            try {
                await this.removeAd();
            }
            catch { }
        }
        this.lastVisibility = shouldBeVisible;
    }

    public onWindowStateChanged(state: any) {
        if (state) {
            if (state.window_state === "minimized") {
                this.shouldBeVisibleInWindowState = false;
                this.recheckVisibility();
            }
            else if(state.window_state === "normal" || state.window_state === "maximized") {
                this.shouldBeVisibleInWindowState = true;
                this.recheckVisibility();
            }
        }
    }
}
