import OverwolfPathResolver from "@/overwolf/provider_overrides/PathResolver/OverwolfPathResolver";
import R2Error from "@/r2modmanPlus/src/model/errors/R2Error";
import { DataFolderProviderImpl } from "@/r2modmanPlus/src/r2mm/system/DataFolderProviderImpl";

export class OverwolfDataFolderProvider extends DataFolderProviderImpl {
    readonly overrideFile: string = ".thunderstoremm"

    /**
     * Call C# plugin to write the override file and update plugins
     * internal state to reflect the change.
     */
    async writeOverrideFile(folderPath: string): Promise<void> {
        try {
            const resolver = new OverwolfPathResolver();
            await resolver.waitForPlugin();
            await resolver.setDataFolder(folderPath);
        } catch (err) {
            throw R2Error.fromThrownValue(err, "Failed to change data folder");
        }
    }
}
