import {NodeChildProcessProvider} from "@/r2modmanPlus/src/providers/node/child_process/child_process";
import PluginGlobals from "@/overwolf/PluginGlobals";

function getOverwolfPlugin(): Promise<any> {
    return new Promise((resolve, reject) => {
        overwolf.extensions.current.getExtraObject("exec", (result: any) => {
            if (result.status === "success") {
                resolve(result.object);
            } else {
                reject(result);
            }
        });
    });
}

export const OverwolfChildProcess: NodeChildProcessProvider = {
    exec: (...args) => getOverwolfPlugin().then(plugin => plugin.Start(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, ...args)),
    execSync: (...args) => {
        throw new Error("execSync is not currently supported by the Exec plugin");
    }
}