import ManifestV2 from '@/r2modmanPlus/src/model/ManifestV2';
import FsProvider from "@/r2modmanPlus/src/providers/generic/file/FsProvider";

import FsOverride from "@/overwolf/provider_overrides/node/fs/FsOverride";
import { OverwolfProtocolProvider } from '@/overwolf/provider_overrides/protocol/OverwolfProtocolProvider';

interface IconCache {
    [key: string]: string | undefined;
}

// 1x1 px transparent.
const INLINE_FALLBACK = 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNkYAAAAAYAAjCB0C8AAAAASUVORK5CYII=';

export class ModIconCache {
    private static CACHE: IconCache = {}
    private static readonly PREFIX = 'data:image/png;base64,';
    private static readonly FALLBACK = '/unknown.png';

    private static async getIcon(mod: ManifestV2) {
        const fs = FsProvider.instance as FsOverride;
        const cacheKey = `${mod.getName()}-${mod.getVersionNumber()}`;

        if (ModIconCache.CACHE[cacheKey] === undefined) {
            if (mod.getIcon() === ModIconCache.FALLBACK) {
                ModIconCache.CACHE[cacheKey] = OverwolfProtocolProvider.getPublicAssetUrl(ModIconCache.FALLBACK);
            } else {
                try {
                    const b64 = await fs.readBase64File(mod.getIcon());
                    ModIconCache.CACHE[cacheKey] = ModIconCache.PREFIX + b64.toString();
                } catch (e) {
                    console.error(
                        'ModIconCache failed to read mod icon and the default fallback icon',
                        mod.getIcon(),
                        e
                    );
                    ModIconCache.CACHE[cacheKey] = INLINE_FALLBACK;
                }
            }
        }

        return ModIconCache.CACHE[cacheKey] as string;
    }

    /**
     * Read icon files from disk and set to ManifestV2 as base64 encoded
     * strings. A simple cache is used to avoid repeated file system
     * calls.
     */
    public static async setIconsForMods(mods: ManifestV2[]) {
        const iconSetters = mods
            .filter((mod) => !mod.getIcon().startsWith(ModIconCache.PREFIX))
            .map(async (mod) => mod.setIcon(await ModIconCache.getIcon(mod)));

        await Promise.all(iconSetters);
    }
}
