import {createApp} from 'vue'
import AppWrapper from './overwolf/AppWrapper.vue';
import router from './overwolf/router';
import store from './overwolf/store/index';
import './r2modmanPlus/src/css/app.scss';
import './overwolf/assets/override.scss';
import 'floating-vue/dist/style.css';

import {library} from '@fortawesome/fontawesome-svg-core';
import {
    faArrowRightFromLine,
    faArrowUpRightFromSquare,
    faBell,
    faBoxOpen,
    faCheck,
    faChevronDown,
    faCircleCheck,
    faCircleUser,
    faCircleXmark,
    faClipboard,
    faClipboardCheck,
    faCloudArrowDown,
    faCloudExclamation,
    faCloudXmark,
    faCog,
    faDash,
    faDownload,
    faEdit,
    faPlayCircle,
    faQuestionCircle,
    faSearch,
    faSpinner,
    faSunBright,
    faWindowMaximize,
    faWindowRestore,
    faXmarkLarge
} from '@fortawesome/pro-regular-svg-icons';
import {
    faMoon as fasMoon,
    faPlayCircle as fasPlayCircle,
    faShareAlt as fasShareAlt
} from '@fortawesome/pro-solid-svg-icons';
import {FontAwesomeIcon} from '@fortawesome/vue-fontawesome';
import * as Sentry from "@sentry/vue";
import {Event as SentryEvent, EventHint, Severity} from "@sentry/types";
import FloatingVue from 'floating-vue';

import "./telemetry";
import {getCdns, setCdns} from "@/r2modmanPlus/src/providers/cdn/CdnHostList";
import {addPackageUrlTransformer} from "@/r2modmanPlus/src/providers/cdn/PackageUrlTransformer";

// Setup Fontawesome icon library. List all the icons you want to use as
// <font-awesome-icon /> here.
library.add(
    faArrowRightFromLine, faArrowUpRightFromSquare, faBell, faBoxOpen, faCheck,
    faChevronDown, faCircleCheck, faCircleUser, faCircleXmark,
    faClipboard, faClipboardCheck, faCloudArrowDown, faCloudXmark, faCloudExclamation,
    faCog, faDash, faDownload, faEdit,
    faPlayCircle, faQuestionCircle, faSearch, faSpinner, faSunBright,
    faWindowMaximize, faWindowRestore, faXmarkLarge,

    fasMoon, fasPlayCircle, fasShareAlt
);

FloatingVue.options.distance = 12;

// @ts-ignore
window.app = {
    // Electron style platform information isn't available via Overwolf other than here:
    // https://dev.overwolf.com/ow-native/reference/utils/ow-utils/#example-data-success
    // Since we currently only support Windows, explicitly say we're win32 for now.
    getPlatform: () => 'win32',

    // This is for r2mm and is no-op in tsmm.
    checkForApplicationUpdates: () => Promise.resolve(),
}

if (import.meta.env.MODE === 'development') {
    console.log("Overriding CDNs");
    setCdns([
        { protocol: 'http', host: 'localhost:82'},
        ...getCdns()
    ]);
    addPackageUrlTransformer(url => {
        if (url.startsWith("https://thunderstore.io")) {
            const remainingUrl = url.substring("https://thunderstore.io".length);
            return "http://localhost:81" + remainingUrl;
        }
        return url;
    })
}

const app = createApp(AppWrapper, {
    store: store
})
    .component('font-awesome-icon', FontAwesomeIcon)
    .use(FloatingVue)
    .use(router);

// For sending data to Sentry during runtime.
Sentry.init({
    enabled: import.meta.env.MODE === 'production',

    // @ts-ignore
    app,
    dsn: import.meta.env.VITE_SENTRY_DSN,
    release: `${import.meta.env.VITE_SENTRY_PROJECT}@${import.meta.env.APP_VERSION}`,
    autoSessionTracking: true,
    allowUrls: [
        `overwolf-extension://${import.meta.env.VITE_OVERWOLF_ID}`,
    ],
    beforeSend: (event: SentryEvent, hint?: EventHint): PromiseLike<SentryEvent | null> | SentryEvent | null => {
        const excludePatterns = [
            // Ignore errors caused by ad providers, identified by Google Publisher Tag (gpt)
            /\/managed\/js\/gpt\//,
            /tag\/js\/gpt/,
            // Ignore errors caused by Overwolf's ad-related JS.
            /libs\/ads\/latest\/owads/
        ];

        for (const frame of (event.exception?.values?.[0]?.stacktrace?.frames ?? [])) {
            for (const pattern of excludePatterns) {
                if (pattern.test(frame.filename ?? "")) {
                    return null;
                }
            }
        }

        return event;
    }
});

export const VueApp = app.mount('#app');

try {
    store.dispatch("subscription/refreshActivePlan");
} catch (e) {
    Sentry.withScope(scope => {
        scope.setLevel(Severity.Error);
        scope.setExtra("additional_info", {
            fluff: "Subscription status called before overwolf API is initialized?",
            overwolf: overwolf,
            getDetailedActivePlans: overwolf.profile.subscriptions.getDetailedActivePlans,
        });
        Sentry.captureException(e);
    });
}

overwolf.profile.subscriptions.onSubscriptionChanged.addListener((event) => {
    store.dispatch("subscription/refreshActivePlan");
});
