import {
  SimpleSpanProcessor,
  WebTracerProvider,
} from "@opentelemetry/sdk-trace-web";
import { Resource } from "@opentelemetry/resources";
import { SemanticResourceAttributes } from "@opentelemetry/semantic-conventions";
import { XMLHttpRequestInstrumentation } from "@opentelemetry/instrumentation-xml-http-request";
import { registerInstrumentations } from "@opentelemetry/instrumentation";
import { ZoneContextManager } from "@opentelemetry/context-zone";
import {
  OTLPTraceExporter,
} from "@opentelemetry/exporter-trace-otlp-http";

const exporter = new OTLPTraceExporter({
  url: import.meta.env.VITE_OTLP_TRACES_ENDPOINT,
  headers: JSON.parse(import.meta.env.VITE_OTLP_HEADERS || "{}"),
});

const resource = Resource.default().merge(new Resource({
  [SemanticResourceAttributes.SERVICE_NAME]: import.meta.env.VITE_OTLP_SERVICE_NAME,
  [SemanticResourceAttributes.SERVICE_VERSION]: import.meta.env.APP_VERSION || "0.1.0",
}));

const providerWithZone = new WebTracerProvider({ resource: resource });
providerWithZone.addSpanProcessor(new SimpleSpanProcessor(exporter));

providerWithZone.register({
  contextManager: new ZoneContextManager(),
});

registerInstrumentations({
  instrumentations: [
    new XMLHttpRequestInstrumentation({
      // Ignore everything except domains with thunderstore.io in them
      ignoreUrls: [/^(?:(?!thunderstore\.io).)*$/],
    }),
  ],
});
