import { ActionContext, GetterTree } from 'vuex';

import { State as StoreState } from '@/overwolf/store/index';

interface State {
    plan: overwolf.profile.Plan | undefined;
    lastRefresh: Date | undefined;
}
interface SaveState {
    plan: overwolf.profile.Plan | undefined;
    lastRefresh: string | undefined;
}

interface SubscriptionModuleGetters {
    isSubscribed: boolean;
    isSubscribedViaOw: boolean;
    isSubscribedViaTs: boolean;
    canSubscribe: boolean;
    showAdSidebar: boolean;
}
interface PartialStoreGetters {
    "auth/subscriptionExpires": Date|null;
}

type Context = ActionContext<State, StoreState>;

const localStorageKey = "planState";
const loadState = (): State => {
    const cached = window.localStorage.getItem(localStorageKey);
    if (cached) {
        try {
            const parsed = JSON.parse(cached) as SaveState;
            return {
                plan: parsed.plan,
                lastRefresh: parsed.lastRefresh ? new Date(parsed.lastRefresh) : undefined,
            }
        } catch (e) {
            console.error(e);
        }
    }
    return {
        plan: undefined,
        lastRefresh: undefined,
    }
};
const saveState = (state: State) => {
    window.localStorage.setItem(localStorageKey, JSON.stringify({
        plan: state.plan,
        lastRefresh: state.lastRefresh,
    }));
}

// Max time a cached plan is considered valid (e.g. offline usage)
const planExpiry = 1000 * 60 * 60 * 24 * 14; // 14 days
const planId = Number(import.meta.env.VITE_OVERWOLF_SUBSCRIPTION_PLAN_ID);

export default {
    namespaced: true,

    state: (): State => (loadState()),

    mutations: {
        setPlan: function(
            state: State,
            payload: {
                plan: overwolf.profile.Plan | undefined,
                lastRefresh: Date,
            }
        ): void {
          state.plan = payload.plan;
          state.lastRefresh = payload.lastRefresh;
          saveState(state);
        },
    },

    actions: {
        async refreshActivePlan({ commit }: Context) {
            overwolf.profile.subscriptions.getDetailedActivePlans((info) => {
                if (info.success) {
                    const plan = info.plans?.find((p) => p.planId === planId);

                    commit("setPlan", {
                        plan: plan && plan.state !== "revoked" ? plan : undefined,
                        lastRefresh: new Date(),
                    });
                }
                if (info.error) {
                    console.error(info.error);
                }
            });
        },
        async openSubscribePage() {
            overwolf.utils.openStore({
              page: overwolf.utils.enums.eStorePage.SubscriptionPage
            });
        },
    },

    getters: <GetterTree<State, StoreState>>{
        /**
         * Two paraller subscription methods exists currently:
         * - via Overwolf for mod manager only
         * - via Thunderstore for both website and mod manager.
         * Either will suffice to remove the ads on mod manager.
         */
        isSubscribed: (
            state: State,
            getters: SubscriptionModuleGetters
        ): boolean => {
            return getters.isSubscribedViaOw || getters.isSubscribedViaTs;
        },
        isSubscribedViaOw: (
            state: State
        ): boolean => {
            if (state.plan === undefined) return false;
            if (!state.lastRefresh) return false;
            if (new Date().getTime() - state.lastRefresh.getTime() > planExpiry) return false;
            return true;
        },
        isSubscribedViaTs: (
            state: State,
            getters: SubscriptionModuleGetters,
            rootState: StoreState,
            rootGetters: PartialStoreGetters
        ): boolean => {
            const expires = rootGetters["auth/subscriptionExpires"];
            if (expires === null) return false;

            const today = new Date();
            today.setHours(0, 0, 0, 0);
            return today.getTime() < expires.getTime();
        },
        canSubscribe: (state: State, getters: any): boolean => {
            return !!planId && !getters.isSubscribed;
        },
        showAdSidebar: (state: State, getters: any): boolean => {
            return !getters["isSubscribed"];
        },
    }
}
