import * as Sentry from "@sentry/vue";
import { ActionTree, GetterTree } from 'vuex';

import { TsModsModule as R2ModsModule } from "@/r2modmanPlus/src/store/modules/TsModsModule";

import { State as RootState } from '@/overwolf/store/index';
import * as TelemetryUtils from "@/overwolf/utils/telemetry";

interface State extends ReturnType<typeof R2ModsModule.state> {
    // Add any new state variables here.
}

export const TsModsModule = {
    namespaced: true,

    state: (): State => ({
        ...R2ModsModule.state(),
    }),

    getters: <GetterTree<State, RootState>>{
        ...R2ModsModule.getters,
    },

    mutations: {
        ...R2ModsModule.mutations,
    },

    actions: <ActionTree<State, RootState>>{
        ...R2ModsModule.actions,

        // Don't call this directly from components.
        _r2mmSyncPackageList: R2ModsModule.actions.syncPackageList,

        // Wrap R2MM's syncPackageList to add telemetry.
        async syncPackageList({dispatch, rootState}) {
            const tracer = TelemetryUtils.getPackageListUpdateTracer();

            await tracer.startActiveSpan("package-list-update", async (span) => {
                TelemetryUtils.setPackageListUpdateSpanAttributes(
                    span,
                    import.meta.url,
                    "refreshThunderstoreModList",
                    rootState.activeGame.internalFolderName
                );

                try {
                    await dispatch('_r2mmSyncPackageList');
                    TelemetryUtils.recordSuccess(span);
                } catch (e) {
                    TelemetryUtils.recordError(span, e);
                    Sentry.captureException(e);
                } finally {
                    span.end();
                }
            });
        }
    }
};
