import { ActionTree, MutationTree } from 'vuex';

import { State as RootState } from '@/overwolf/store/index';
import ProfileExportModule from '@/r2modmanPlus/src/store/modules/ProfileExportModule';

interface State extends ReturnType<typeof ProfileExportModule.state> {
    isSharePending: boolean;
}

export const TsProfileExportModule = {
    namespaced: true,

    state: (): State => ({
        ...ProfileExportModule.state(),
        isSharePending: false
    }),

    mutations: <MutationTree<State>>{
        ...ProfileExportModule.mutations,

        setIsSharePending(state: State, isSharePending: boolean) {
            state.isSharePending = isSharePending;
        },
    },

    actions: <ActionTree<State, RootState>>{
        ...ProfileExportModule.actions,
    }
};
