<template>
    <div>
        <TitleBar />

        <div class="root-container">
          <div id="router-content" class="root-content">
            <div class="overflow-handler">
              <router-view v-if="loaded" />
            </div>

            <ErrorModal />
            <OverwolfLoginModal />
          </div>

          <div v-if="store.getters['subscription/showAdSidebar']" class="root-sidebar">
            <sidebar/>
          </div>
        </div>
      <Footer>
        <template v-slot:right>
          <StatusIndicator />
        </template>
      </Footer>
    </div>
</template>

<script lang="ts" setup>
import "bulma-switch/dist/css/bulma-switch.min.css";
import LinkProvider from "@/r2modmanPlus/src/providers/components/LinkProvider";
import OverwolfLinkImpl from "@/overwolf/provider_overrides/link/OverwolfLinkImpl";
import ProfileProvider from "@/r2modmanPlus/src/providers/ror2/model_implementation/ProfileProvider";
import ProfileImpl from "@/r2modmanPlus/src/r2mm/model_implementation/ProfileImpl";
import FsProvider from "@/r2modmanPlus/src/providers/generic/file/FsProvider";
import FsOverride from "@/overwolf/provider_overrides/node/fs/FsOverride";
import OverwolfPathResolver from "@/overwolf/provider_overrides/PathResolver/OverwolfPathResolver";
import PathResolver from "@/r2modmanPlus/src/r2mm/manager/PathResolver";
import path from "@/r2modmanPlus/src/providers/node/path/path";
import LogOutputProvider from "@/r2modmanPlus/src/providers/ror2/data/LogOutputProvider";
import LogOutput from "@/r2modmanPlus/src/r2mm/data/LogOutput";
import LoggerProvider, {LogSeverity} from "@/r2modmanPlus/src/providers/ror2/logging/LoggerProvider";
import {Logger} from "@/r2modmanPlus/src/r2mm/logging/Logger";
import InteractionProvider from "@/r2modmanPlus/src/providers/ror2/system/InteractionProvider";
import OverwolfInteractionProvider from "@/overwolf/provider_overrides/InteractionProvider/OverwolfInteractionProvider";
import {DataFolderProvider} from "@/r2modmanPlus/src/providers/ror2/system/DataFolderProvider";
import {OverwolfDataFolderProvider} from "@/overwolf/provider_overrides/DataFolderProvider/OverwolfDataFolderProvider";
import ProfileInstallerProvider from "@/r2modmanPlus/src/providers/ror2/installing/ProfileInstallerProvider";
import ZipProvider from "@/r2modmanPlus/src/providers/generic/zip/ZipProvider";
import OverwolfZipProvider from "@/overwolf/provider_overrides/ZipProvider/OverwolfZipProvider";
import LocalModInstaller from "@/r2modmanPlus/src/r2mm/installing/LocalModInstaller";
import LocalModInstallerProvider from "@/r2modmanPlus/src/providers/ror2/installing/LocalModInstallerProvider";
import ThunderstoreDownloaderProvider
  from "@/r2modmanPlus/src/providers/ror2/downloading/ThunderstoreDownloaderProvider";
import ManagerSettings from "@/r2modmanPlus/src/r2mm/manager/ManagerSettings";
import BindOverwolfOverrides from "@/overwolf/components/overrides/BindOverwolfOverrides";
import ManagerInformation from "@/r2modmanPlus/src/_managerinf/ManagerInformation";
import OverwolfThunderstoreDownloader from "@/overwolf/provider_overrides/downloader/OverwolfThunderstoreDownloader";
import VersionNumber from "@/r2modmanPlus/src/model/VersionNumber";
import PlatformInterceptorProvider
  from "@/r2modmanPlus/src/providers/generic/game/platform_interceptor/PlatformInterceptorProvider";
import {getStore} from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import OverwolfPlatformInterceptorImpl
  from "@/overwolf/provider_overrides/platform_interceptor/OverwolfPlatformInterceptorImpl";
import axios from "axios";
import * as Sentry from "@sentry/vue";
import InstallationRules from "@/r2modmanPlus/src/r2mm/installing/InstallationRules";
import GenericProfileInstaller from "@/r2modmanPlus/src/r2mm/installing/profile_installers/GenericProfileInstaller";
import Sidebar from "@/overwolf/components/Sidebar.vue";
import {appTitle} from "@/overwolf/router/routes";
import Footer from "@/overwolf/components/Footer.vue";
import StatusIndicator from "@/overwolf/components/StatusIndicator.vue";
import TitleBar from "@/overwolf/components/TitleBar.vue";
import {isDevMode} from "@/overwolf/utils/global";
import OverwolfLoginModal from "@/overwolf/components/modals/OverwolfLoginModal.vue";
import ErrorModal from '@/r2modmanPlus/src/components/modals/ErrorModal.vue';
import {onMounted, ref} from "vue";
import {useUtilityComposable} from "@/r2modmanPlus/src/components/composables/UtilityComposable";
import {useRouter} from "vue-router";
import {OverwolfPathImplementation} from "@/overwolf/provider_overrides/node/path/OverwolfPath";
import {provideProtocolImplementation} from "@/r2modmanPlus/src/providers/generic/protocol/ProtocolProvider";
import {OverwolfProtocolProvider} from "@/overwolf/provider_overrides/protocol/OverwolfProtocolProvider";
import {State} from "@/overwolf/store";

const {
  checkCdnConnection,
  hookBackgroundUpdateThunderstoreModList,
  hookModInstallingViaProtocol,
} = useUtilityComposable();

const loaded = ref<boolean>(false);

const store = getStore<State>();
const router = useRouter();

onMounted(async () => {

  ManagerInformation.APP_NAME = "Thunderstore Mod Manager";
  const appVersion = import.meta.env.APP_VERSION as string;
  ManagerInformation.VERSION = appVersion
      ? new VersionNumber(appVersion)
      : new VersionNumber("0.0.0");

  const fs = new FsOverride();
  FsProvider.provide(() => fs);

  const linkProvider = new OverwolfLinkImpl();
  LinkProvider.provide(() => linkProvider);
  await linkProvider.waitForPlugin();

  ProfileProvider.provide(() => new ProfileImpl());

  const resolver = new OverwolfPathResolver();
  await resolver.waitForPlugin();

// Load settings using the default game before the actual game is selected.
  const settings: ManagerSettings = await store.dispatch('resetActiveGame');

  hookBackgroundUpdateThunderstoreModList(router);

  const dataFolderPath = (await resolver.getDataFolder()).Value;

  let consistentDataFolderPath = dataFolderPath.replace(/\\/g, "/");
  if (!dataFolderPath.endsWith("DataFolder")) {
    consistentDataFolderPath = path.join(consistentDataFolderPath, "DataFolder");
  }

  const finalDataFolder = settings.getContext().global.dataDirectory.length > 0 ? settings.getContext().global.dataDirectory : consistentDataFolderPath;

  await resolver.setDataFolder(finalDataFolder);

// Initialize VueX store with the value read from Dexie store.
  store.commit("setIsDarkTheme", settings.getContext().global.darkTheme);

  PathResolver.APPDATA_DIR = OverwolfPathImplementation.normalize(finalDataFolder);
  PathResolver.ROOT = OverwolfPathImplementation.normalize(finalDataFolder);

  LogOutputProvider.provide(() => LogOutput.getSingleton());

  const downloader = new OverwolfThunderstoreDownloader();
  ThunderstoreDownloaderProvider.provide(() => downloader);

  LocalModInstallerProvider.provide(() => new LocalModInstaller());
  ProfileInstallerProvider.provide(() => new GenericProfileInstaller());
  LoggerProvider.provide(() => new Logger());

  const overwolfInteractionProvider = new OverwolfInteractionProvider();
  InteractionProvider.provide(() => overwolfInteractionProvider);
  await overwolfInteractionProvider.waitForPlugin();

  DataFolderProvider.provide(() => new OverwolfDataFolderProvider());

  const zipProvider = new OverwolfZipProvider();
  ZipProvider.provide(() => zipProvider);
  await zipProvider.waitForPlugin();

  PlatformInterceptorProvider.provide(() => new OverwolfPlatformInterceptorImpl());

  provideProtocolImplementation(() => OverwolfProtocolProvider);

// TODO: remove the wrapping `if` when auth stuff is published.
  if (isDevMode) {
    store.dispatch("auth/verifySession");
  }

  BindOverwolfOverrides.bind();

  InstallationRules.apply();
  InstallationRules.validate();

  loaded.value = true;

  window.onerror = function (msg: string | Event) {
    if (msg instanceof Event) {
      LoggerProvider.instance.Log(LogSeverity.ERROR, msg.toString());
    } else {
      LoggerProvider.instance.Log(LogSeverity.ERROR, msg);
    }
  }

  axios.interceptors.request.use(value => {
    const data = {
      headers: value.headers,
      url: value.url,
      method: value.method
    }
    LoggerProvider.instance.Log(LogSeverity.INFO, `Request data: ${JSON.stringify(data)}`);
    return value;
  });

  axios.interceptors.response.use(
      value => {

        const response = {
          headers: value.headers,
          status: value.status,
          statusText: value.statusText,
          responseUrl: value.request.responseURL
        }

        LoggerProvider.instance.Log(LogSeverity.INFO, `Response data: ${JSON.stringify(response)}`);

        if (value.data === undefined) {
          // Shouldn't happen. Log to Sentry.
          const error = new Error();
          error.name = `Response from [${response.responseUrl}] has data content of undefined. Status code: [${value.status}]`;
          error.message = JSON.stringify(response);
          Sentry.withScope(function(scope) {
            scope.setFingerprint(["Empty request response", (value.status || 0).toString()]);
            scope.setExtra("error", error);
            Sentry.captureMessage(`Response from [${response.responseUrl}] has data content of undefined. Status code: [${value.status}]`, scope);
          });
        }

        return value;
      },
      error => {
        LoggerProvider.instance.Log(LogSeverity.BREAKING, `Failed response: ${JSON.stringify(error)}`)
        return error;
      }
  );

  await checkCdnConnection();
  document.title = appTitle();

  hookModInstallingViaProtocol(router);  // Depends on interaction provider.

  router.afterEach(to => {
    document.title = to.meta && to.meta.title() || appTitle();
  });

  store.commit('updateModLoaderPackageNames');
  store.dispatch('tsMods/updateExclusions');
});
</script>

<style lang="scss">
    :root {
      --titlebar-height: 43px;
      --footer-height: 31px;
    }

    html, body {
        overflow: hidden !important;
        border-radius: 0 !important;
    }

    #app {
        overflow: hidden;
    }

    .root-container {
      width: 100vw;
      display: flex;
    }

    .root-content {
      flex: 1;
      width: 100%;
      height: calc(calc(100vh - var(--titlebar-height)) - var(--footer-height));
      max-height: calc(calc(100vh - var(--titlebar-height)) - var(--footer-height));
      overflow: hidden;
      position: relative;
    }

    .overflow-handler {
      width: 100%;
      height: 100%;
      overflow: auto;
      overflow-x: hidden;
      display: flex;
      flex-direction: column;
    }

    .root-sidebar {
      width: auto;
      height: calc(calc(100vh - var(--titlebar-height)) - var(--footer-height));
    }

    /* When updating Bulma to v0.9.4, the position changed to relative. */
    button.modal-close {
      position: absolute;
    }

    /* Bulma-slider v2.0.5 changes the order in which rulesets occur in
       processed CSS, causing selectors with same specificity to
       override each other, causing e.g. text inputs to have transparent
       borders. v2.0.4 works but outputs annoying deprecation warnings. */
    body {
      /* Overwritten Bulma declarations with higher specificity. */
      .input,
      .select select,
      .textarea {
        background-color: var(--input-background-color,var(--background,#fff));
        border-color: var(--input-border-color,var(--border,#e1e1e1));
        border-radius: 4px;
        color: var(--input-color,var(--text-strong,#363636));
      }
    }

    .modal {
      position: absolute !important;
    }

</style>
