import GameDirectoryResolverProvider from "@/r2modmanPlus/src/providers/ror2/game/GameDirectoryResolverProvider";
import R2Error from "@/r2modmanPlus/src/model/errors/R2Error";
import OverwolfPathResolver from "@/overwolf/provider_overrides/PathResolver/OverwolfPathResolver";
import ManagerSettings from "@/r2modmanPlus/src/r2mm/manager/ManagerSettings";
import GameManager from "@/r2modmanPlus/src/model/game/GameManager";
import Game from "@/r2modmanPlus/src/model/game/Game";
import * as path from "path";
import FsProvider from "@/r2modmanPlus/src/providers/generic/file/FsProvider";
import {Logger} from "@/r2modmanPlus/src/r2mm/logging/Logger";
import {LogSeverity} from "@/r2modmanPlus/src/providers/ror2/logging/LoggerProvider";

export default class OverwolfGameDirectoryResolver extends GameDirectoryResolverProvider {

    private resolver = new OverwolfPathResolver();
    private currentDir: string = "";

    async getSteamDirectory(): Promise<string | R2Error> {
        const settings = await ManagerSettings.getSingleton(GameManager.activeGame);
        await settings.load();
        if (settings.getContext().global.steamDirectory === null) {
            return await this.resolver.waitForPlugin().then(async () => {
                try {
                    const steamDir = await this.resolver.getSteamDirectory();
                    if (steamDir.length > 0) {
                        return steamDir;
                    } else {
                        return new R2Error("Unable to find Steam folder", "", "Set the Steam folder in the manager settings");
                    }
                } catch (e) {
                    const msg = e instanceof Error ? e.message : `${e}`;
                    await new Logger().Log(LogSeverity.ERROR, msg);
                    return new R2Error("Unable to find Steam folder", "", "Set the Steam folder in the manager settings");;
                }
            });
        }
        await this.resolver.updateSteamDirectory(settings.getContext().global.steamDirectory!);
        return settings.getContext().global.steamDirectory!;
    }

    async getDirectory(game: Game): Promise<string | R2Error> {
        const settings = await ManagerSettings.getSingleton(game);
        await settings.load();
        let resolvedGameDir = settings.getContext().gameSpecific.gameDirectory ?? "";
        if (resolvedGameDir.length === 0) {
            if (game.isInstalledViaSteam) {
                await this.resolver.waitForPlugin();
                try {
                    const dirs = await this.resolver.getPotentialGameDirectories();
                    if (dirs[0] !== undefined && dirs[0].length > 0) {
                        if (dirs[0].endsWith(game.steamFolderName)) {
                            resolvedGameDir = dirs[0];
                        } else {
                            resolvedGameDir = path.join(path.dirname(this.sanitizePath(dirs[0])), this.sanitizePath(game.steamFolderName));
                        }
                    } else {
                        resolvedGameDir = dirs[0] ?? "";
                    }
                } catch (e) {
                    resolvedGameDir = "";
                    const msg = e instanceof Error ? e.message : `${e}`;
                    await new Logger().Log(LogSeverity.ERROR, msg);
                }
            }
        }
        if (resolvedGameDir.trim().length > 0) {
            if (this.currentDir !== resolvedGameDir) {
                this.currentDir = resolvedGameDir;
                try {
                    if (await FsProvider.instance.exists(resolvedGameDir)) {
                        await this.resolver.updateGameDirectory(resolvedGameDir);
                    }
                } catch (e) {
                    const msg = e instanceof Error ? e.message : `${e}`;
                    return new R2Error(
                        `Folder [${resolvedGameDir}] does not exist`,
                        msg,
                        null
                    );
                }
            }
            return resolvedGameDir;
        }
        return new R2Error("Game folder could not be found", "", `Set the ${game.displayName} folder in the Settings screen.`);
    }

    private sanitizePath(path: string) {
        return path.replace(new RegExp("\\\\", "g"), "/");
    }
}
