import {Platform} from "@/r2modmanPlus/src/model/schema/ThunderstoreSchema";
import GameRunnerProvider from "@/r2modmanPlus/src/providers/generic/game/GameRunnerProvider";
import GameDirectoryResolverProvider from "@/r2modmanPlus/src/providers/ror2/game/GameDirectoryResolverProvider";
import OverwolfGameDirectoryResolver from "@/overwolf/provider_overrides/game/resolvers/OverwolfGameDirectoryResolver";
import PlatformInterceptorProvider
    from "@/r2modmanPlus/src/providers/generic/game/platform_interceptor/PlatformInterceptorProvider";
import {PackageLoader} from "@/r2modmanPlus/src/model/schema/ThunderstoreSchema";
import OverwolfGameRunner from "@/overwolf/provider_overrides/game/runners_v2/OverwolfGameRunner";
import OverwolfEgsGameRunner from "@/overwolf/provider_overrides/game/runners_v2/OverwolfEgsGameRunner";
import OverwolfXboxGamePassGameRunner
    from "@/overwolf/provider_overrides/game/runners_v2/OverwolfXboxGamePassGameRunner";

const overwolfGameRunner = new OverwolfGameRunner();
const overwolfEgsGameRunner = new OverwolfEgsGameRunner();
const overwolfXboxGamePassGameRunner = new OverwolfXboxGamePassGameRunner();
const overwolfDirectoryResolver = new OverwolfGameDirectoryResolver();

type LoaderRunnersType = {
    [loader in PackageLoader]: GameRunnerProvider
}

type RunnerType = {
    [platkey in Platform]: LoaderRunnersType
};

type ResolverType = {
    [platkey in Platform]: GameDirectoryResolverProvider
};


function buildRunners(runner: GameRunnerProvider): LoaderRunnersType {
    return {
        [PackageLoader.BEPINEX]: runner,
        [PackageLoader.MELONLOADER]: runner,
        [PackageLoader.NORTHSTAR]: runner,
        [PackageLoader.NONE]: runner,
        [PackageLoader.GODOTML]: runner,
        [PackageLoader.SHIMLOADER]: runner,
        [PackageLoader.LOVELY]: runner,
        [PackageLoader.RETURN_OF_MODDING]: runner,
        [PackageLoader.GDWEAVE]: runner,
        [PackageLoader.RECURSIVE_MELONLOADER]: runner,
        [PackageLoader.BEPISLOADER]: runner,
        [PackageLoader.UMM]: runner,
        [PackageLoader.RIVET]: runner,
    }
}

const RUNNERS: RunnerType = {
    [Platform.STEAM]: buildRunners(overwolfGameRunner),
    [Platform.EPIC_GAMES_STORE]: buildRunners(overwolfEgsGameRunner),
    [Platform.OCULUS_STORE]: buildRunners(overwolfGameRunner),
    [Platform.OTHER]: buildRunners(overwolfGameRunner),
    [Platform.STEAM_DIRECT]: buildRunners(overwolfGameRunner),
    [Platform.ORIGIN]: buildRunners(overwolfGameRunner),
    [Platform.XBOX_GAME_PASS]: buildRunners(overwolfXboxGamePassGameRunner),
};

const RESOLVERS: ResolverType = {
    [Platform.STEAM]: overwolfDirectoryResolver,
    [Platform.EPIC_GAMES_STORE]: overwolfDirectoryResolver,
    [Platform.OCULUS_STORE]: overwolfDirectoryResolver,
    [Platform.OTHER]: overwolfDirectoryResolver,
    [Platform.STEAM_DIRECT]: overwolfDirectoryResolver,
    [Platform.ORIGIN]: overwolfDirectoryResolver,
    [Platform.XBOX_GAME_PASS]: overwolfDirectoryResolver
};

export default class OverwolfPlatformInterceptorImpl extends PlatformInterceptorProvider {

    public getRunnerForPlatform(platform: Platform, loader: PackageLoader): GameRunnerProvider | undefined {
        if (RUNNERS[platform][loader] !== undefined) {
            return RUNNERS[platform][loader];
        }
        return undefined;
    }

    public getDirectoryResolverForPlatform(platform: Platform): GameDirectoryResolverProvider | undefined {
        if (RESOLVERS[platform] !== undefined) {
            return RESOLVERS[platform];
        }
        return undefined;
    }

}
