// @ts-nocheck
import InteractionProvider, {
    InteractionProviderFileProperties,
    InteractionProviderFolderProperties
} from "@/r2modmanPlus/src/providers/ror2/system/InteractionProvider";
import PluginGlobals from "@/overwolf/PluginGlobals";
import OverwolfResult from "@/overwolf/provider_overrides/OverwolfResult";
import R2Error from "@/r2modmanPlus/src/model/errors/R2Error";
import OverwolfProtocol from "@/overwolf/overwolf_specific/OverwolfProtocol";

let hookId = 0;

export default class OverwolfInteractionProvider extends InteractionProvider {

    private plugin: any;
    private loaded: boolean = false;

    constructor() {
        super();
        // @ts-ignore-line
        overwolf.extensions.current.getExtraObject("win-dialog", (result) => {
            if (result.status === "success") {
                this.plugin = result.object;
                this.loaded = true;
            }
        });
    }

    public async waitForPlugin(): Promise<void> {
        return new Promise(resolve => {
            if (this.loaded) {
                resolve();
            } else {
                const interval = setInterval(() => {
                    if (this.loaded) {
                        resolve();
                        clearInterval(interval);
                    }
                }, 10);
            }
        });
    }

    async selectFolder(options: InteractionProviderFolderProperties): Promise<string[]> {
        return new Promise((resolve, reject) => {
            this.plugin.SelectFolder(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, options.title, options.defaultPath, (r: string) => {
               const result = JSON.parse(r) as OverwolfResult;
               if (result.TypeString === "ERROR") {
                   reject(new R2Error("Failed to select folder", result.Value, null));
               } else {
                   resolve((result.Value as string[]).map(this.sanitizePath));
               }
            });
        });
    }

    async selectFile(options: InteractionProviderFileProperties): Promise<string[]> {
        return new Promise((resolve, reject) => {
            this.plugin.SelectFile(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, options.title, "", JSON.stringify(options.filters), (r: string) => {
                const result = JSON.parse(r) as OverwolfResult;
                if (result.TypeString === "ERROR") {
                    reject(new R2Error("Failed to select folder", result.Value, null));
                } else {
                    resolve((result.Value as string[]).map(this.sanitizePath));
                }
            });
        });
    }

    restartApp() {
        overwolf.extensions.relaunch();
    }

    hookModInstallProtocol(callback: (data: any) => void) {
        const currentHook = ++hookId;
        const listener = (proto: OverwolfProtocol) => {
            if (currentHook == hookId) {
                if (proto.origin.toLowerCase() === "urlscheme") {
                    callback(decodeURIComponent(proto.parameter));
                }
            } else {
                overwolf.extensions.onAppLaunchTriggered.removeListener(listener);
            }
        };

        overwolf.extensions.onAppLaunchTriggered.addListener(listener);
    }

    copyToClipboard(value: string) {
        overwolf.utils.placeOnClipboard(value);
    }

    private sanitizePath(path: string) {
        return path.replace(new RegExp("\\\\", "g"), "/");
    }
}