<template>
  <div class="sidebar">
    <div class="header">
      <p>
        <span>Ads support development</span>
        <i class="fas fa-heart heart"></i>
        <a v-if="showRemoveAds" v-on:click="onRemoveAdsClick">Subscribe</a>
      </p>
    </div>
    <template v-if="useTallAd">
      <overwolf-ad v-if="showAds" :width="400" :height="600" id="ad-ow-tall"/>
    </template>
    <template v-else>
      <overwolf-ad v-if="showAds" :width="300" :height="250" id="ad-ow-display"/>
      <overwolf-ad v-if="showAds" :width="400" :height="300" id="ad-ow-video"/>
    </template>
  </div>
</template>

<script lang="ts" setup>
import OverwolfAd from "@/overwolf/components/OverwolfAd.vue";
import {computed} from "vue";
import {getStore} from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import {State} from "@/overwolf/store";

const store = getStore<State>();

async function onRemoveAdsClick() {
  await store.dispatch("subscription/openSubscribePage");
}

const showRemoveAds = computed<boolean>(() => store.getters["subscription/canSubscribe"]);
const showAds = computed<boolean>(() => !store.getters["subscription/isSubscribed"]);
const useTallAd = computed<boolean>(() => true);
</script>

