import ThunderstoreDownloaderProvider
    from "@/r2modmanPlus/src/providers/ror2/downloading/ThunderstoreDownloaderProvider";
import ThunderstoreCombo from "@/r2modmanPlus/src/model/ThunderstoreCombo";
import { DownloadStatusEnum } from "@/r2modmanPlus/src/model/enums/DownloadStatusEnum";
import R2Error from "@/r2modmanPlus/src/model/errors/R2Error";
import PathResolver from "@/r2modmanPlus/src/r2mm/manager/PathResolver";
import * as path from "path";
import FileWriteError from "@/r2modmanPlus/src/model/errors/FileWriteError";
import ZipExtract from "@/r2modmanPlus/src/r2mm/installing/ZipExtract";
import Profile from "@/r2modmanPlus/src/model/Profile";
import ManagerInformation from "@/r2modmanPlus/src/_managerinf/ManagerInformation";
import OverwolfDownloaderPlugin from "@/overwolf/provider_overrides/downloader/OverwolfDownloaderPlugin";
import FileUtils from "@/r2modmanPlus/src/utils/FileUtils";
import * as DownloadUtils from "@/r2modmanPlus/src/utils/DownloadUtils";

export default class OverwolfThunderstoreDownloader extends ThunderstoreDownloaderProvider {

    public async download(
        combos: ThunderstoreCombo[],
        ignoreCache: boolean,
        totalProgressCallback: (downloadedSize: number, modName: string, status: DownloadStatusEnum, err: R2Error | null) => void
    ): Promise<void> {
        if (combos.length === 0) {
            throw new R2Error('No mods to download', 'An empty list of mods was passed to the downloader');
        }

        let modInProgressName = combos[0].getMod().getName();
        let finishedModsDownloadedSize = 0;

        const singleModProgressCallback = (downloadedBytes: number, status: DownloadStatusEnum, err: R2Error | null) => {
            let modInProgressDownloadedSize;

            if (status === DownloadStatusEnum.FAILED) {
                throw err;
            } else if (status === DownloadStatusEnum.DOWNLOADING || status === DownloadStatusEnum.EXTRACTING) {
                modInProgressDownloadedSize = downloadedBytes;
            } else if (status === DownloadStatusEnum.EXTRACTED) {
                finishedModsDownloadedSize += downloadedBytes;
                modInProgressDownloadedSize = 0;
            } else {
                console.error(`Ignore unknown status code "${status}"`);
                return;
            }

            totalProgressCallback(
                finishedModsDownloadedSize + modInProgressDownloadedSize,
                modInProgressName,
                status,
                err
            );
        }

        for (const comboInProgress of combos) {
            modInProgressName = comboInProgress.getMod().getName();

            if (!ignoreCache && await DownloadUtils.isVersionAlreadyDownloaded(comboInProgress)) {
                singleModProgressCallback(0, DownloadStatusEnum.EXTRACTED, null);
                continue;
            }

            try {
                await this._downloadCombo(comboInProgress, singleModProgressCallback);
                await this._extractDownloaded(comboInProgress, singleModProgressCallback);
            } catch(e) {
                throw R2Error.fromThrownValue(e, `Failed to download mod ${comboInProgress.getVersion().getFullName()}`);
            }
        }
    }

    private async _downloadCombo(combo: ThunderstoreCombo, callback: (downloadedBytes: number, status: DownloadStatusEnum, err: R2Error | null) => void): Promise<void> {
        const downloader = new OverwolfDownloaderPlugin();
        const folderRoot = this.getModCacheFolder(combo);
        await FileUtils.ensureDirectory(folderRoot);
        let downloadUrl = combo.getVersion().getDownloadUrl();
        downloadUrl = downloadUrl.replace(/http:\/\//i, "https://");

        return downloader.download(
            combo,
            downloadUrl,
            path.join(folderRoot, combo.getVersion().getVersionNumber().toString() + ".zip"),
            downloadedSize => callback(downloadedSize, DownloadStatusEnum.DOWNLOADING, null)
        );
    }

    private async _extractDownloaded(
        combo: ThunderstoreCombo,
        callback: (downloadedSize: number, status: DownloadStatusEnum, err: R2Error | null) => void
    ): Promise<void> {
        const folderRoot = this.getModCacheFolder(combo);
        const comboSize = combo.getVersion().getFileSize();
        callback(comboSize, DownloadStatusEnum.EXTRACTING, null);

        await this.extractDownload(folderRoot, combo, (success: boolean, error?: R2Error) => {
            if (success) {
                callback(comboSize, DownloadStatusEnum.EXTRACTED, null);
            } else {
                callback(comboSize, DownloadStatusEnum.FAILED, error || null);
            }
        });
    }

    private getModCacheFolder(combo: ThunderstoreCombo): string {
        const cacheDirectory = path.join(PathResolver.MOD_ROOT, 'cache');
        return path.join(cacheDirectory, combo.getMod().getFullName());
    }

    /* DEPRECATED */
    public async saveToFile(response: Buffer, combo: ThunderstoreCombo, callback: (success: boolean, error?: R2Error) => void) {
    }

    private async extractDownload(rootFolder: string, combo: ThunderstoreCombo, callback: (success: boolean, error?: R2Error) => void) {
        try {
            await ZipExtract.extractAndDelete(
                rootFolder,
                combo.getVersion().getVersionNumber().toString() + '.zip',
                combo.getVersion().getVersionNumber().toString(),
                callback
            );
        } catch(e) {
            const msg = e instanceof Error ? e.message : `${e}`;
            callback(false, new FileWriteError(
                'File write error',
                `Failed to write downloaded zip of ${combo.getMod().getFullName()} to profile folder of ${Profile.getActiveProfile().getProfilePath()}. \nReason: ${msg}`,
                `Try running ${ManagerInformation.APP_NAME} as an administrator`
            ));
        }
    }

}
