import { Json } from "@/overwolf/types";

export class StorageManager {
    readonly namespace: string;
    storage = window.localStorage;

    constructor(namespace = "") {
        this.namespace = namespace;
    }

    _getKey(key: string): string {
        return this.namespace ? `${this.namespace}.${key}` : key;
    }

    _get(key: string) {
        return this.storage.getItem(this._getKey(key));
    }

    _set(key: string, value: string) {
        this.storage.setItem(this._getKey(key), value);
    }

    _remove(key: string) {
        this.storage.removeItem(this._getKey(key));
    }

    getBool(key: string) {
        const value = this.getValue(key);

        if (value === "true") {
            return true;
        } else if (value === "false") {
            return false;
        }

        return null;
    }

    getValue(key: string): string | null {
      return this._get(key);
    }

    getJSON<T extends Json>(key: string): T | null {
        const value = this._get(key);
        return value === null ? null : JSON.parse(value);
    }

    setBool(key: string, value: boolean) {
        this.setValue(key, value ? "true" : "false");
    }

    setValue(key: string, value: string) {
        this._set(key, value);
    }

    setJSON(key: string, value: Json) {
        this._set(key, JSON.stringify(value));
    }

    removeValue(key: string) {
        this._remove(key);
    }
}
