<template>
    <div :class="['modal', 'z-top', {'is-active': isOpen}]">
        <div class="modal-background" @click="close"></div>
        <div class="modal-content">
            <div class="card">
                <header class="card-header">
                    <p class="card-header-title">
                        <slot name="title" />
                    </p>
                </header>
                <div class="card-content">
                    <slot name="body" />
                </div>
                <div class="card-footer">
                    <slot name="footer" />
                </div>
            </div>
        </div>
        <button
            v-if="!preventDefaultClose"
            class="modal-close is-large"
            aria-label="close"
            @click="close"
        />
    </div>
</template>

<script lang="ts" setup>
import { State } from "@/overwolf/store";
import { getStore } from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import { computed } from "vue";

/**
 * Based on the reusable Modal component in r2mm, but uses VueX store to
 * manage modals visibility.
 *
 * Currently only supports "card" style modals. "Notification" style
 * modals could be supported by accepting an addition type prop and
 * varying the contents of div.modal-content with v-ifs based on it.
 */

const store = getStore<State>();

/**
 * @property {string} vuexStateKey The key in the VueX store that holds the modal's state
 * @property {string} vuexCloseMutation The mutation to call when the modal is closed
 * @property {boolean} [preventDefaultClose] Don't show the X button and prevent closing the modal by clicking the background. Use this when you need to force the user to make a choice and execute extra functionality based on it.
 */
type BaseModalProps = {
    vuexStateKey: string;
    vuexCloseMutation: string;
    preventDefaultClose?: boolean;
}

const props = withDefaults(defineProps<BaseModalProps>(), { preventDefaultClose: false });
const isOpen = computed<boolean>(() => store.state.modals[props.vuexStateKey]);

function close() {
    if (!props.preventDefaultClose) {
        store.commit(props.vuexCloseMutation);
    }
}

</script>
