<template>
    <BaseModal
        id="ow-login-modal"
        vuexStateKey="isOverwolfLoginModalOpen"
        vuexCloseMutation="closeOverwolfLoginModal"
        preventDefaultClose
    >
        <template v-slot:title>Overwolf login required</template>
        <template v-slot:body>
            <p>
                You need to log into your Overwolf account to proceed.
                Login form has been opened in the main Overwolf window.
            </p>
        </template>
        <template v-slot:footer>
            <Button class="button danger" :onClick="customClose">Cancel</Button>
        </template>
    </BaseModal>
</template>

<script lang="ts" setup>
import BaseModal from "@/overwolf/components/modals/BaseModal.vue";
import Button from "@/overwolf/components/TsButton.vue";
import { overwolfLoginHelper } from "@/overwolf/utils/auth";

/**
 * This component is shown to users who are not logged in
 * on the Overwolf app and attempt to log into the mod manager.
 */

function customClose() {
    overwolfLoginHelper.cancelWaitForLogin();
}
</script>
