<template>
  <div class="ad-container" :style="style">
    <div class="ad-background" />
    <div :id="id" ref="ad-element" :style="style" class="ad-element" />
  </div>
</template>

<script lang="ts" setup>
import OverwolfAdInstance from "@/overwolf/overwolf_specific/OverwolfAdManager";
import {computed, onMounted, onUnmounted, ref} from "vue";

type OverwoldAdProps = {
  width: number;
  height: number;
  id: string;
}

const props = defineProps<OverwoldAdProps>();
const adInstance = ref();

onMounted(() => {
  adInstance.value = new OverwolfAdInstance(document.getElementById(props.id)!, props.width, props.height);
});

onUnmounted(() => {
  adInstance.value.deconstruct();
});

const style = computed(() => `width: ${props.width}px; height: ${props.height}px`);
</script>

<style lang="scss" scoped>
.ad-container {
  position: relative;
  background-color: black;
}
.ad-element {
  position: absolute;
  width: 100%;
  height: 100%;
  z-index: 1;
}
.heart {
  color: var(--TSSC-accent-red);
  margin-left: 2px;
}

.ad-background {
  position: absolute;
  bottom: 0;
  right: 0;
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 15%;
  text-align: center;
  color: var(--TSSC-LM-text-ternary);
}

.html--dark {
  .ad-background {
    color: var(--TSSC-text-secondary);
  }
}
</style>
