import FsProvider from "@/r2modmanPlus/src/providers/generic/file/FsProvider";
import StatInterface from "@/r2modmanPlus/src/providers/generic/file/StatInterface";
import FsOperations from "@/overwolf/provider_overrides/node/fs/FsOperations";
import FsStat from "@/overwolf/provider_overrides/node/fs/FsStat";
import OverwolfResult from "@/overwolf/provider_overrides/OverwolfResult";
import R2Error from "@/r2modmanPlus/src/model/errors/R2Error";
import * as path from "path";
import PluginGlobals from "@/overwolf/PluginGlobals";
import FileUtils from "@/r2modmanPlus/src/utils/FileUtils";

export default class FsOverride extends FsProvider {

    private plugin!: FsOperations;

    constructor() {
        super();
        // @ts-ignore-line
        overwolf.extensions.current.getExtraObject("r2io-operations", (result) => {
            if (result.status === "success") {
                this.plugin = result.object;
            }
        })
    }


    // Unimplemented because it only applies to Linux.
    async chmod(path: string, mode: string | number): Promise<void> {
        return;
    }

    async copyFile(from: string, to: string): Promise<void> {
        return new Promise((resolve, reject) => {
            this.plugin.CopyFile(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, from, to, r => {
                const result = JSON.parse(r);
                if (result.TypeString === "ERROR") {
                    return reject(new R2Error("Failed to copy file", result.Value, null));
                } else if (result.TypeString === "ERROR_DISK_SPACE") {
                    const err = new R2Error("Not enough space remaining on disk", result.Value, "Clean the mod cache via Settings or change the drive the data folder is located on.");
                    err.errorReferenceString = result.TypeString;
                    return reject(err);
                }
                return resolve();
            });
        });
    }

    async copyFolder(from: string, to: string): Promise<void> {
        return new Promise(async (resolve, reject) => {
            try {
                for (const value of (await this.readdir(from))) {
                    if ((await this.lstat(path.join(from, value))).isDirectory()) {
                        await this.copyFolder(path.join(from, value), path.join(to, value));
                    } else {
                        await FileUtils.ensureDirectory(to);
                        await this.copyFile(path.join(from, value), path.join(to, value));
                    }
                }
            } catch (e) {
                reject(R2Error.fromThrownValue(e, "Failed to copy folder"));
            }

            resolve();
        });
    }

    async exists(path: string): Promise<boolean> {
        return new Promise((resolve, reject) => {
            this.plugin.Exists(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, path, r => {
                const result = JSON.parse(r) as OverwolfResult;
                if (result.TypeString === "ERROR") {
                    console.log("Exists err", path, result);
                    reject(new R2Error("Error checking existence", result.Value, null));
                } else {
                    resolve(result.Value);
                }
            });
        });
    }

    async lstat(path: string): Promise<StatInterface> {
        return new Promise((resolve, reject) => {
            this.plugin.Lstat(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, path, r => {
                const result: OverwolfResult = JSON.parse(r);
                if (result.TypeString === "LSTAT") {
                    const stat = result.Value as FsStat;
                    const mdate = new Date();
                    mdate.setTime(stat.Mtime);
                    resolve({
                        isDirectory: () => stat.IsDirectory,
                        isFile: () => !stat.IsDirectory,
                        mtime: mdate,
                        size: stat.Size,
                    });
                } else {
                    console.log("lstat Error:", result);
                    reject(new Error(result.Value));
                }
            });
        });
    }

    setModifiedTime(path: string, time: Date): Promise<void> {
        return new Promise((resolve, reject) => {
            this.plugin.SetModifiedTime(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, path, time.getTime(), r => {
                const result: OverwolfResult = JSON.parse(r);
                if (result.TypeString === "ERROR") {
                    reject(new Error(result.Value));
                } else {
                    resolve();
                }
            });
        });
    }

    async mkdirs(path: string): Promise<void> {
        return new Promise((resolve, reject) => {
            this.plugin.Mkdirs(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, path, r => {
                const result = JSON.parse(r);
                if (result.TypeString === "ERROR") {
                    console.log("mkdirs Error:", result);
                    const msg = `Folder "${path}" could not be created. ${result.Value}`;
                    reject(new R2Error("Failed to create folder", msg));
                } else {
                    resolve();
                }
            });
        })
    }

    async readFile(path: string): Promise<Buffer> {
        return new Promise((resolve, reject) => {
            this.plugin.ReadFile(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, path, r => {
                const result = JSON.parse(r);
                if (result.TypeString === "BUFFER") {
                    resolve(Buffer.from(result.Value));
                } else {
                    reject(new Error(r));
                }
            });
        });
    }

    base64FromZip(path: string): Promise<string> {
        return this.readBase64File(path).then(value => value.toString());
    }

    async readBase64File(path: string): Promise<Buffer> {
        return new Promise((resolve, reject) => {
            this.plugin.ReadBase64File(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, path, r => {
                const result = JSON.parse(r);
                if (result.TypeString === "BUFFER") {
                    resolve(Buffer.from(result.Value));
                } else {
                    reject(new Error(result.Value));
                }
            });
        });
    }

    async readdir(path: string): Promise<string[]> {
        return new Promise((resolve, reject) => {
            this.plugin.ReadDir(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, path, r => {
                const result = JSON.parse(r);
                if (result.TypeString === "STRING_ARRAY") {
                    resolve(result.Value);
                } else {
                    const err = new R2Error('Readdir Error', result.Value, null);
                    reject(err);
                }
            });
        });
    }

    async rename(path: string, newPath: string): Promise<void> {
        return new Promise((resolve, reject) => {
            this.plugin.Rename(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, path, newPath, r => {
                const result = JSON.parse(r);
                if (result.TypeString === "ERROR") {
                    const err = new R2Error('Rename Error', result.Value, null);
                    console.log(err);
                    reject(err);
                } else {
                    resolve();
                }
            });
        });
    }

    async rmdir(path: string): Promise<void> {
        return new Promise((resolve, reject) => {
            this.plugin.Rmdir(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, path, r => {
                const result = JSON.parse(r);
                if (result.TypeString === "ERROR") {
                    const err = new R2Error('Rmdir Error', result.Value, null);
                    reject(err);
                } else {
                    resolve();
                }
            });
        });
    }

    async unlink(path: string): Promise<void> {
        return new Promise((resolve, reject) => {
            this.plugin.Unlink(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, path, r => {
                const result = JSON.parse(r);
                if (result.TypeString === "ERROR") {
                    const err = new R2Error('Readdir Error', result.Value, null);
                    reject(err);
                } else {
                    resolve();
                }
            });
        });
    }

    async writeFile(path: string, content: string | Buffer): Promise<void> {
        let contentToSend: any = content;
        return new Promise((resolve, reject) => {
            if (content instanceof Buffer) {
                contentToSend = [...content];
            }
            this.plugin.WriteFile(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, path, contentToSend, result => {
                const data = JSON.parse(result) as OverwolfResult;
                if (data.TypeString === "ERROR") {
                    console.log("Write err", data);
                    reject(new Error(data.Value));
                } else if (data.TypeString === "ERROR_DISK_SPACE") {
                    const err = new R2Error("Not enough space remaining on disk", data.Value, "Clean the mod cache via Settings or change the drive the data folder is located on.");
                    err.errorReferenceString = data.TypeString;
                    return reject(err);
                } else {
                    resolve();
                }
            });
        });
    }

    stat(path: string): Promise<StatInterface> {
        return this.lstat(path);
    }

    realpath(path: string): Promise<string> {
        return new Promise(resolve => resolve(path));
    }
}
