import OverwolfLinkImpl from "@/overwolf/provider_overrides/link/OverwolfLinkImpl";

export const isDateString = (value: any) => !isNaN(Date.parse(value));

export const isDevMode = import.meta.env.VITE_AUTTIDEV === "true";

export const openLink = async (url: string) => {
    const implementation = new OverwolfLinkImpl();
    await implementation.waitForPlugin();
    implementation.openLink(url);
};
