<template>
    <button v-if="username" type="button" @click="toUserPage">
        <img v-if="avatarUrl" :src="avatarUrl" alt="" />
        <font-awesome-icon v-else icon="fa-regular fa-circle-user" />
        <span>{{ store.getters["shownUsername"] }}</span>
    </button>
    <button v-else-if="isLoading" type="button">
        <font-awesome-icon icon="fa-regular fa-spinner" spin />
        <span>Wait...</span>
    </button>
    <FaButton v-else icon="fa-circle-user" label="Log in" :onClick="login" />
</template>

<script lang="ts" setup>
import FaButton from "@/overwolf/components/FaButton.vue";
import {overwolfLoginHelper, OverwolfLoginHelperEvent} from "@/overwolf/utils/auth";
import R2Error from "@/r2modmanPlus/src/model/errors/R2Error";
import {getStore} from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import {State} from "@/overwolf/store";
import {computed, onMounted, onUnmounted, ref} from "vue";
import {useRouter} from "vue-router";

const store = getStore<State>();
const router = useRouter();

const isLoading = ref<boolean>(false);

const avatarUrl = computed<string | undefined>(() => store.state.auth.user.overwolf?.avatar);
const username = computed(() => store.getters["shownUsername"]);

onMounted(() => {
  overwolfLoginHelper.addEventListener(onLoginEvent);
});

onUnmounted(() => {
  overwolfLoginHelper.removeEventListener(onLoginEvent);
});

async function onLoginEvent(event: OverwolfLoginHelperEvent) {
    isLoading.value = event.type === "started";

    if (event.type === "error") {
        store.commit(
            "error/handleError", R2Error.fromThrownValue(event.error, "Login failed")
        );
    }
}

async function login() {
    await overwolfLoginHelper.login();
}

async function toUserPage() {
    if (router.currentRoute.value.name !== "user") {
        await router.push({name: "user"});
    }
}
</script>

<style lang="scss" scoped>
button {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    height: 32px;
    border: none;
    border-radius: 4px;
    color: var(--TSDC-navitem-text);
    background-color: var(--TSDC-navitem-bg);
    transition:
        background-color var(--TSMM-default-transition-duration),
        color var(--TSMM-default-transition-duration);

    &:hover {
        cursor: pointer;
        color: var(--TSDC-navitem-text-hover);
        background-color: var(--TSDC-navitem-bg-hover);
    }

    svg,
    img {
        width: 16px;
        height: 16px;
        border-radius: 50%;
    }

    span {
        font-size: 12px;
    }
}
</style>
