import { ActionTree, GetterTree } from 'vuex';

import ManifestV2 from '@/r2modmanPlus/src/model/ManifestV2';
import ProfileModule from "@/r2modmanPlus/src/store/modules/ProfileModule";

import { State as RootState } from '@/overwolf/store/index';
import { ModIconCache } from '@/overwolf/utils/ModIconCache';

interface State extends ReturnType<typeof ProfileModule.state> {
    // Add any new state variables here.
}

export const TsProfileModule = {
    namespaced: true,

    state: (): State => ({
        ...ProfileModule.state(),
    }),

    getters: <GetterTree<State, RootState>>{
        ...ProfileModule.getters,
    },

    mutations: {
        ...ProfileModule.mutations,
    },

    actions: <ActionTree<State, RootState>>{
        ...ProfileModule.actions,

        // Don't call this directly from components.
        _r2mmUpdateModList: ProfileModule.actions.updateModList,

        async updateModList({dispatch}, modList: ManifestV2[]) {
            await ModIconCache.setIconsForMods(modList);
            await dispatch('_r2mmUpdateModList', modList);
        },
    }
};
