import * as Sentry from "@sentry/vue";
import axios from "axios";

import { State } from "@/overwolf/store/index";
import {
    isTsProfile,
    isTsSession,
    OwProfile,
    TsProfile,
    TsSession
} from "@/overwolf/types";
import { getStore } from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import {
    getAxiosWithTimeouts,
    isNetworkError,
    isResponseTimeout
} from "@/r2modmanPlus/src/utils/HttpUtils";
import { TypedEventEmitter, TypedListener } from "@/utils/TypedEventEmitter";

type SessionToken = overwolf.profile.SessionTokenResponse;

const BASE_URL = "https://accounts.overwolf.com/tokens/short-lived"
const OW_ID = `extensionId=${import.meta.env.VITE_OVERWOLF_ID}`;
const PROFILE_URL = `${BASE_URL}/users/profile?${OW_ID}`;
const VERIFY_TOKEN_URL = `${BASE_URL}/verify?${OW_ID}`;

const TS_DOMAIN = import.meta.env.VITE_TS_DOMAIN;
const LOGIN_URL = `${TS_DOMAIN}/api/experimental/auth/overwolf/login/`;
const LOGOUT_URL = `${TS_DOMAIN}/api/experimental/auth/delete/`;
const TS_PROFILE_URL = `${TS_DOMAIN}/api/experimental/current-user/`;

const auth_axios = getAxiosWithTimeouts();
auth_axios.defaults.headers.common["Content-Type"] = "application/json";

// Fetch Overwolf session token from their API.
export const getSessionToken = async (): Promise<SessionToken> => {
    return await new Promise(async (resolve) => {
        overwolf.profile.generateUserSessionToken(resolve);
    });
}

// Use session token to fetch user's Overwolf profile.
// Is not guaranteed to return OwProfile object on errors, use
// isOwProfile to validate returned data if it matters.
export const tryGetUserProfile = async (token: string) => {
    const headers = {"Authorization": `Bearer ${token}`};
    let res;

    try {
        res = await auth_axios.get(PROFILE_URL, {headers});
    } catch (e) {
        console.error(`Fetching OW profile resulted in error "${e}"`);
        Sentry.captureException(e);
        return {} as unknown;
    }

    return res.data as OwProfile|unknown;
}

// Get Thunderstore session by sending Overwolf JWT to backend.
// Thrown Erros may be shown to users on error modal.
export const getThunderstoreSession = async (token: string) => {
    const baseError = "Authenticating with Thunderstore backend failed";
    let res;

    try {
        res = await auth_axios.post<TsSession>(LOGIN_URL, {jwt: token});
    } catch (e) {
        if (isNetworkError(e)) {
            throw new Error(`${baseError} (client or server offline)`);
        }

        if (isResponseTimeout(e) || axios.isCancel(e)) {
            throw new Error(`${baseError} (timeout)`);
        }

        if (axios.isAxiosError(e)) {
            throw new Error(`${baseError} (HTTP status ${e.response?.status})`);
        }

        throw new Error(`${baseError} (${e})`);
    }

    if (!isTsSession(res.data)) {
        throw new Error(`${baseError} (malformed response)`);
    }

    return res.data;
}

type ProfileResponse = {
    status: "refreshed";
    profile: TsProfile;
} | {
    status: "expired"|"offline"|"malformed"|"error";
    profile?: undefined;
}

// Check that the session is still valid by fetching a fresh TS profile.
// Since this is used in a "background process", most errors are
// suppressed so the caller can keep using cached information.
export const getThunderstoreProfile = async (sessionId: string): Promise<ProfileResponse> => {
    const headers = {"Authorization": `Session ${sessionId}`};
    let res;

    try {
        res = await auth_axios.get<TsProfile>(TS_PROFILE_URL, {headers});
    } catch (e) {
        if (isNetworkError(e) || isResponseTimeout(e) || axios.isCancel(e)) {
            return {status: "offline"};
        }

        if (axios.isAxiosError(e) && e.response?.status === 401) {
            // Unauthenticated, most likely due to an expired session.
            return {status: "expired"};
        }

        Sentry.captureException(e);
        return {status: "error"};
    }

    // Response was successful but payload doesn't match expectations.
    if (!isTsProfile(res.data)) {
        return {status: "malformed"};
    }

    return {status: "refreshed", profile: res.data};
}

// Try to end existing Thunderstore session.
export const terminateThunderstoreSession = async (sessionId: string) => {
    const data = {};
    const headers = {"Authorization": `Session ${sessionId}`};

    try {
        await auth_axios.post(LOGOUT_URL, data, {headers});
    } catch (e) {
        // We don't care whether the logout succeeded or failed, the
        // session id will be thrown away anyway.
        Sentry.captureException(e);
    }
}

// Is the Overwolf session token with 15 minute TTL still valid?
// Currently used only in debugging, so error handling is lax.
export const verifySessionToken = async (token: string) => {
    const headers = {"Authorization": `Bearer ${token}`};
    let res;

    try {
        res = await auth_axios.get(VERIFY_TOKEN_URL, {headers});
    } catch (e) {
        console.error(`Session token "${token}" not verified: ${e}`);
        return false;
    }

    return res.status === 200;
}

export type OverwolfLoginHelperEvent = {
    type: "started"|"cancelled"|"completed";
    error?: undefined;
} | {
    type: "error";
    error: Error;
};

class OverwolfLoginHelper {
    private eventEmitter = new TypedEventEmitter<OverwolfLoginHelperEvent>();

    constructor() {
        this.loginEventHandler = this.loginEventHandler.bind(this);
    }

    public addEventListener(listener: TypedListener<OverwolfLoginHelperEvent>) {
        this.eventEmitter.addListener(listener);
    }

    public removeEventListener(listener: TypedListener<OverwolfLoginHelperEvent>) {
        this.eventEmitter.removeListener(listener);
    }

    public async login() {
        this.eventEmitter.emit({type: "started"});
        let token: string|null = null;

        try {
            token = await this.tryGetOverwolfJwt();
        } catch (e) {
            this.emitError(e);
            return;
        }

        // Direct user to log into Overwolf. Rest of the auth process is
        // handled by an event listener, so return immediately.
        if (!token) {
            this.waitForLogin();
            return;
        }

        const session = await this.getThunderstoreSession(token);

        if (session) {
            try {
                await this.saveToVueX(token, session);
            } catch (e) {
                this.emitError(e);
                return;
            }
        }

        this.eventEmitter.emit({type: "completed"});
    }

    public cancelWaitForLogin() {
        overwolf.profile.onLoginStateChanged.removeListener(this.loginEventHandler);
        this.store.commit("closeOverwolfLoginModal");
        this.eventEmitter.emit({type: "cancelled"});
    }

    private get store() {
        return getStore<State>();
    }

    private emitError(error: unknown) {
        this.eventEmitter.emit({
            type: "error",
            error: error instanceof Error ? error : new Error(`${error}`)
        });
    }

    private async tryGetOverwolfJwt() {
        const tokenResponse = await getSessionToken();

        if (tokenResponse.success) {
            if (!tokenResponse.token) {
                throw new Error("Successful token response contained no token");
            }

            return tokenResponse.token;
        } else if (tokenResponse.error?.toLowerCase() === "not logged in") {
            return null;
        }

        throw new Error(tokenResponse.error ?? "Undefined error");
    }

    private waitForLogin() {
        overwolf.profile.onLoginStateChanged.addListener(this.loginEventHandler);
        this.store.commit("openOverwolfLoginModal");
        overwolf.profile.openLoginDialog();
    }

    /**
     * Example event for login:
     * {status: "success", connectionState: "Online", username: "antti.maki"}
     *
     * Example event for logout:
     * {status: "success", connectionState: "Offline", username: ""}
     */
    private async loginEventHandler(event: overwolf.profile.LoginStateEvent) {
        // Only react to successful login event.
        if (event.status !== "success" || event.connectionState !== "Online") {
            return;
        }

        this.cancelWaitForLogin();
        let token: string|null = null;

        try {
            token = await this.tryGetOverwolfJwt();
        } catch (e) {
            this.emitError(e);
            return;
        }

        if (!token) {
            this.emitError("Can't get a token although user just logged in.");
            return;
        }

        const session = await this.getThunderstoreSession(token);

        if (session) {
            try {
                await this.saveToVueX(token, session);
            } catch (e) {
                this.emitError(e);
                return;
            }
        }

        this.eventEmitter.emit({type: "completed"});
    }

    private async getThunderstoreSession(token: string) {
        try {
            return await getThunderstoreSession(token);
        } catch (e) {
            this.emitError(e);
            return null;
        }
    }

    private async saveToVueX(token: string, session: TsSession) {
        await this.store.dispatch("auth/login", {
            owToken: token,
            tsSessionId: session.session_id,
            tsProfile: session.profile
        });
    }
}

export const overwolfLoginHelper = new OverwolfLoginHelper();
