import R2Error from "@/r2modmanPlus/src/model/errors/R2Error";
import PluginGlobals from "@/overwolf/PluginGlobals";
import opentelemetry, { Span, SpanStatusCode } from "@opentelemetry/api";
import ManagerInformation from "@/r2modmanPlus/src/_managerinf/ManagerInformation";
import { SemanticAttributes } from "@opentelemetry/semantic-conventions";
import ThunderstoreCombo from "@/r2modmanPlus/src/model/ThunderstoreCombo";
import * as Sentry from "@sentry/vue";

type Callback<EventArgs> = (event: EventArgs) => void;

type DownloadProgressEvent = {
    BytesReceived: number;
    TotalBytesToReceive: number;
};
type DownloadFailEvent = {
    ErrorType: string;
    Message: string;
};


interface IDownloadPlugin {
    DownloadFile: (
      appName: string,
      appId: string,
      url: string,
      destination: string,
      onSuccess: Callback<void>,
      onFail: Callback<DownloadFailEvent>,
    ) => void;
    PollProgress: (
      destination: string,
      onProgress: Callback<DownloadProgressEvent>,
    ) => void;
}

export default class OverwolfDownloaderPlugin {
    private plugin?: IDownloadPlugin;
    private tracer = opentelemetry.trace.getTracer(
      "thunderstore.mod-manager.plugins.downloader",
      `semver:${ManagerInformation.VERSION}`
    );

    private async getPlugin(): Promise<IDownloadPlugin> {
        if (!this.plugin) {
            this.plugin = await new Promise<IDownloadPlugin>((resolve, reject) => {
                overwolf.extensions.current.getExtraObject("downloader", (result: any) => {
                    if (result.status === "success") {
                        resolve(result.object);
                    } else {
                        reject("Failed to load downloader");
                    }
                });
            });
        }
        return this.plugin;
    }

    /**
     * Wraps the actual download function in a trace collector.
     */
    public download(combo: ThunderstoreCombo | null, url: string, fileName: string, progressCallback: (downloadedSize: number) => void): Promise<void> {
        return this.tracer.startActiveSpan("download", async (span) => {
            span.setAttribute(SemanticAttributes.CODE_FUNCTION, "download");
            span.setAttribute(SemanticAttributes.CODE_FILEPATH, import.meta.url);
            span.setAttribute(SemanticAttributes.HTTP_METHOD, "GET");
            span.setAttribute(SemanticAttributes.HTTP_URL, url);
            if (combo) {
                const ver = combo.getVersion();
                span.setAttribute("thunderstore.package.namespace", combo.getMod().getOwner());
                span.setAttribute("thunderstore.package.name", ver.getName());
                span.setAttribute("thunderstore.package.version", ver.getVersionNumber().toString());
            }
            try {
                await this._download(span, url, fileName, progressCallback);
            } finally {
                span.end();
            }
        });
    }

    private async _download(span: Span, url: string, fileName: string, progressCallback: (downloadedSize: number) => void): Promise<void> {
        const plugin = await this.getPlugin();

        return await new Promise((resolve, reject) => {
            let contentLength = -1;
            const onProgress = (e: DownloadProgressEvent) => {
                if (contentLength < 0) {
                    contentLength = e.TotalBytesToReceive;
                    span.addEvent("First progress event");
                    span.setAttribute("http.response_content_length", contentLength);
                }
                progressCallback(e.BytesReceived);
            }

            // For some reason the callbacks can only be called once from C#,
            // so we need to poll the file size to track download progress...
            const interval = setInterval(() => {
                plugin.PollProgress(fileName, onProgress);
            }, 100);

            const onSuccess = () => {
                clearInterval(interval);
                span.setStatus({ code: SpanStatusCode.OK });
                resolve();
            }
            const onFail = (e: DownloadFailEvent) => {
                clearInterval(interval);
                const message = `${e.ErrorType}: ${e.Message}`;
                const internalException = new Error(message);
                const userException = new R2Error(message, `Download failed for ${url}`);
                span.recordException(internalException);
                span.setStatus({
                    code: SpanStatusCode.ERROR,
                    message: `${e.ErrorType}: ${e.Message}`,
                });
                Sentry.captureException(internalException);
                reject(userException);
            };
            plugin.DownloadFile(PluginGlobals.APP_NAME, PluginGlobals.APP_ID, url, fileName, onSuccess, onFail);
        });
    }
}
