<template>
    <div
        :class="`status-indicator ${status.severity} ${status.onClick ? 'pointer' : ''}`"
        @click="status.onClick ? status.onClick() : () => null"
        v-tooltip.top="status.tooltip"
    >
        <div class="status-icon">
            <font-awesome-icon fixedWidth :icon="'fa-regular ' + status.icon" />
        </div>

        <div class="text">{{ status.text }}</div>
    </div>
</template>

<script lang="ts" setup>
import {computed} from "vue";
import {getStore} from "@/r2modmanPlus/src/providers/generic/store/StoreProvider";
import {State} from "@/overwolf/store";

const store = getStore<State>();

type IndicatorStatus = {
    text: string,
    icon: string,
    severity: "info" | "warning" | "error",
    onClick?: () => Promise<void>,
    tooltip?: string,
}

const status = computed<IndicatorStatus>(() => {
    if (store.getters['download/conciseDownloadStatus']) {
        return {
            text: store.getters['download/conciseDownloadStatus'],
            icon: "fa-cloud-arrow-down",
            severity: "info"
        };
    } else if (store.getters['tsMods/conciseThunderstoreModListUpdateErrorMessage']) {
        return {
            text: store.getters['tsMods/conciseThunderstoreModListUpdateErrorMessage'],
            icon: "fa-cloud-xmark",
            severity: "error",
            tooltip: "Refresh",
            onClick: () => store.dispatch("tsMods/syncPackageList")
        };
    } else if (store.state.tsMods.isThunderstoreModListUpdateInProgress) {
        return {
            text: "Refreshing online mod list...",
            icon: "fa-cloud-arrow-down",
            severity: "info"
        }
    } else if (store.getters['tsMods/isModListOutdated']) {
        return {
            text: "Outdated online mod list",
            icon: "fa-cloud-exclamation",
            severity: "warning",
            tooltip: "Refresh",
            onClick: () => store.dispatch("tsMods/syncPackageList")
        }
    }
    return {
        text: "Ready",
        icon: "fa-check",
        severity: "info"
    }
});
</script>

<style lang="scss" scoped>

.status-indicator {
    display: flex;
    gap: 8px;

    font-size: 11px;
    line-height: 15px;
    color: var(--TSSC-text-secondary);
}
.status-icon {
    height: 15px;
    font-size: 12px;
}
.pointer {
    cursor: pointer;
}
.error {
    color: var(--TSSC-accent-danger-default);
}
.warning {
    color: var(--TSSC-accent-warning-default);
}

</style>
