<template>
    <button type="button" :disabled="disabled" @click="onClick">
        <slot />
    </button>
</template>

<script lang="ts" setup>
/**
 * Simple button component for TSMM.
 *
 * Prestyled classes:
 *   .cta, .cta2, .danger
 *   .ghost, .cta.ghost, .cta2.ghost, .danger.ghost
 *
 * Note that the default, classless variant is not meant to be used.
 */

type TsButtonProps = {
  disabled?: boolean;
  onClick: () => void;
};

const props = withDefaults(defineProps<TsButtonProps>(), {
  disabled: false
});
</script>

<style lang="scss" scoped>
button {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 0.625rem;
    height: 40px;
    padding: 0 1rem;
    border-width: 1px;
    transition:
        background-color var(--TSMM-default-transition-duration),
        border-color var(--TSMM-default-transition-duration),
        color var(--TSMM-default-transition-duration);

    font-weight: 400;
    font-size: 1rem;
    line-height: 1;
    border-style: solid;
    border-radius: 0.25rem;

    &:hover {
        cursor: pointer;
    }

    &:disabled {
        // Quasar's CSS uses `opacity: 0.6 !important` for all disabled elements
        cursor: default;
    }

    // Dummy value for default variant: this is not meant to be used.
    --main-color: var(--TSSC-border-hover);

    // Pattern for filled buttons
    background-color: var(--main-color);
    border-color: var(--main-color);
    color: #fff;

    // Pattern for ghost buttons - note that default ghost button
    // doesn't follow this pattern and is overwritten below.
    &.ghost {
        background-color: transparent;
        border-color: var(--main-color);
        color: var(--main-color);
    }

    // Call-to-action
    &.cta {
        --main-color: var(--TSSC-accent-secondary-default);
        &:hover { --main-color: var(--TSSC-accent-secondary-hover); }
        &:active { --main-color: var(--TSSC-accent-secondary-active); }
    }

    // // Call-to-action, but different
    &.cta2 {
        --main-color: var(--TSSC-accent-primary);
        &:hover { --main-color: #165ed1; }
        &:active { --main-color: #1459c6; }
    }

    &.danger {
        --main-color: var(--TSSC-accent-danger-default);
        &:hover { --main-color: var(--TSSC-accent-danger-hover); }
        &:active { --main-color: var(--TSSC-accent-danger-active); }
    }
}

// Default ghost button doesn't follow the usual pattern.
// OW ships with Chrome 87, which doesn't support listed selectors in :not().
button.ghost:not(.cta):not(.cta2):not(.danger) {
    background-color: transparent;
    border-color: transparent;
    color: var(--TSDC-text-primary);
    &:hover { border-color: var(--TSSC-border-light-hover); }
    &:active { border-color: var(--TSSC-border-light-active); }
    &:disabled { border-color: #e1e1e1; }
}

.html--dark button.ghost:not(.cta):not(.cta2):not(.danger) {
    &:hover { border-color: var(--TSSC-border-dark-primary); }
    &:active { border-color: var(--TSSC-border-dark-active); }
    &:disabled { border-color: var(--TSSC-border-dark-primary); }
}
</style>
