import OverwolfResult from "@/overwolf/provider_overrides/OverwolfResult";
import R2Error from "@/r2modmanPlus/src/model/errors/R2Error";
import PluginGlobals from "@/overwolf/PluginGlobals";
import ManagerSettings from "@/r2modmanPlus/src/r2mm/manager/ManagerSettings";
import GameManager from "@/r2modmanPlus/src/model/game/GameManager";

export default class OverwolfPathResolver {

    private plugin: any;
    private loaded: boolean = false;

    constructor() {
        // @ts-ignore-line
        overwolf.extensions.current.getExtraObject("r2io-info", (result) => {
            if (result.status === "success") {
                this.plugin = result.object;
                this.loaded = true;
            }
        });
    }

    public async waitForPlugin(): Promise<void> {
        return new Promise(resolve => {
            if (this.loaded) {
                resolve();
            } else {
                const interval = setInterval(() => {
                    if (this.loaded) {
                        resolve();
                        clearInterval(interval);
                    }
                }, 10);
            }
        });
    }

    public async getDataFolder(): Promise<OverwolfResult> {
        return new Promise(resolve => {
            this.plugin.GetDataFolder(PluginGlobals.APP_NAME, (result: string) => {
                return resolve(JSON.parse(result));
            });
        });
    }

    public async setDataFolder(folder: string): Promise<void> {
        return new Promise((resolve, reject) => {
            this.plugin.SetDataFolder(PluginGlobals.APP_NAME, folder, (r: string) => {
                resolve();
            });
        })
    }

    public async getSteamDirectory(): Promise<string> {
        return new Promise(async (resolve, reject) => {
            const settings = await ManagerSettings.getSingleton(GameManager.activeGame);
            await settings.load();
            this.plugin.GetSteamDirectory(async (r: string) => {
                const result = JSON.parse(r) as OverwolfResult;
                if (result.TypeString === "ERROR") {
                    reject(new R2Error("Failed to find Steam folder", result.Value, null));
                } else {
                    if (result.Value) {
                        await this.updateSteamDirectory(result.Value);
                    }
                    resolve(result.Value);
                }
            });
        });
    }

    public async getPotentialGameDirectories(): Promise<string[]> {
        return new Promise(async (resolve, reject) => {
            const settings = await ManagerSettings.getSingleton(GameManager.activeGame);
            await settings.load();
            this.plugin.GetPotentialGameDirectories(PluginGlobals.APP_ID, async (r: string) => {
                const result = JSON.parse(r) as OverwolfResult;
                if (result.TypeString === "ERROR") {
                    return reject(new R2Error("Failed to find game directories", result.Value, null));
                } else {
                    if (result.Value && result.Value.length > 0) {
                        await this.updateGameDirectory(result.Value[0]);
                    }
                    resolve(result.Value);
                }
            });
        });
    }

    public async updateSteamDirectory(path: string): Promise<void> {
        return new Promise(async (resolve, reject) => {
            const settings = await ManagerSettings.getSingleton(GameManager.activeGame);
            await settings.load();
            if (path.trim().length > 0) {
                this.plugin.SetSteamDirectory(PluginGlobals.APP_NAME, path, () => {
                    resolve();
                });
            }
        });
    }

    public async updateGameDirectory(path: string): Promise<void> {
        return new Promise(async (resolve, reject) => {
            const settings = await ManagerSettings.getSingleton(GameManager.activeGame);
            await settings.load();
            if (path.trim().length > 0) {
                this.plugin.SetGameDirectory(PluginGlobals.APP_ID, path, () => {
                    resolve();
                });
            }
        });
    }

}